// Lektionen 43–54 (Offenbarungsreihenfolge, Kairoer Chronologie) – mittelmekkanische Phase
window.LEKTIONEN8 = [
// ───────────────────────── Lektion 43: Fāṭir ─────────────────────────
{
sure: 35, offb: 43, name: "Fāṭir", arab: "سُورَةُ فَاطِرٍ", de: "Der Schöpfer", verse: 45, ort: "Mekka",
zeit: "Mittelmekkanisch – eine Sure der offenen Hand Allahs, in der Phase wachsender Ablehnung",
kurz: "Die Sure beginnt mit einem Lobpreis auf den „Erschaffer (Fāṭir) der Himmel und der Erde, Der die Engel zu Gesandten macht mit Flügeln – zwei, drei und vier“ – und mit einem der tröstlichsten Sätze des Korans: „Was Allah den Menschen an Barmherzigkeit öffnet, das kann niemand zurückhalten; und was Er zurückhält, das kann niemand nach Ihm freigeben.“ Ihr Kernsatz über den Menschen ist schonungslos ehrlich: „O ihr Menschen, ihr seid die Bedürftigen gegenüber Allah – und Allah ist der Unbedürftige, der Lobenswürdige.“ Dazwischen ein Vers, der jedem Lernenden gilt: „Allah fürchten von Seinen Dienern nur die Wissenden (al-ʿulamāʾ)“ – Wissen, das nicht zur Ehrfurcht führt, hat sein Ziel verfehlt. Und am Ende die drei Typen der Erben des Buches: wer sich selbst Unrecht tut, wer die Mitte hält, und wer im Guten vorauseilt – alle drei mit der Tür zum Paradies vor sich.",
schluessel: {arab: "يَا أَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَاءُ إِلَى اللَّهِ ۖ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ", ueb: "O ihr Menschen, ihr seid die Bedürftigen gegenüber Allah, und Allah ist der Unbedürftige, der Lobenswürdige.", ref: "35:15"},
kontext: ["Fāṭir gehört mit Sabaʾ zu den beiden Suren, die mit „al-ḥamdu lillāh“ beginnen und dann den Blick auf Allahs Schöpfermacht richten. Der Name Fāṭir (von faṭara: aufspalten, als Erster hervorbringen – dieselbe Wurzel wie fiṭra, vgl. Lektion 39) meint: Allah hat die Schöpfung nicht nachgebaut, sondern als Erster aus dem Nichts aufbrechen lassen. Ibn ʿAbbās sagte, er habe die Bedeutung von fāṭir erst verstanden, als zwei Beduinen über einen Brunnen stritten und einer sagte: „Ich habe ihn gefaṭarat“ – „ich habe ihn als Erster gegraben“ (Bericht bei aṭ-Ṭabarī zu 35:1).",
"Die Sure spricht in eine Lage, in der der Prophet ﷺ unter der Ablehnung litt. Darum enthält sie gleich zweimal Trost: „Wenn sie dich der Lüge bezichtigen – schon vor dir wurden Gesandte der Lüge bezichtigt“ (35:4) und „So soll deine Seele nicht in Kummer über sie vergehen“ (35:8). Daʿwa-Seelsorge: Du bist nicht verantwortlich für die Herzen, nur für die Übermittlung.",
"Inhaltlich ist Fāṭir eine Sure der Abhängigkeit – im besten Sinn. Sie zählt auf, wovon der Mensch lebt (Regen, Wind, Meere, Früchte, Berge in allen Farben, Menschen und Tiere „in verschiedenen Farben“) und kommt zum Schluss: Die ganze Schöpfung ist bedürftig, nur einer ist ġanī. Wer das begreift, verliert die Angst vor Menschen und den Hochmut gegenüber Menschen zugleich."],
asbab: ["Für Fāṭir ist kein spezifischer Offenbarungsanlass sahih überliefert; sie gehört zu den mekkanischen Grundsatzsuren über Schöpfung, Abhängigkeit und Jenseits."],
begriffe: [
 {arab: "فَاطِر", tr: "fāṭir", wurzel: "f-ṭ-r", erkl: "Der Erschaffer, der als Erster hervorbringt – wörtlich: der Aufspaltende (wie der Keim die Erde aufbricht). Dieselbe Wurzel wie fiṭra (Urnatur) und fiṭr (Fastenbrechen): Allah bringt hervor, was vorher nicht war."},
 {arab: "مَا يَفْتَحِ اللَّهُ", tr: "mā yaftaḥi llāh", wurzel: "f-t-ḥ", erkl: "„Was Allah öffnet …“ (35:2) – das Bild der Tür: Barmherzigkeit kommt nicht durch Beziehungen, Glück oder Strategie, sondern weil Allah öffnet. Und was Er öffnet, kann kein Mensch schließen. Ein Schlüsselvers gegen Neid und Existenzangst."},
 {arab: "الْفُقَرَاء", tr: "al-fuqarāʾ", wurzel: "f-q-r", erkl: "„Die Bedürftigen/Armen“ – faqr heißt ursprünglich: gebrochenes Rückgrat (faqār = Wirbel). Der Mensch ist ohne Allah wie ohne Wirbelsäule. Diese Armut ist keine Schande, sondern Wahrheit: Wer sie anerkennt, wird innerlich reich."},
 {arab: "الْغَنِيّ الْحَمِيد", tr: "al-Ġaniyy al-Ḥamīd", wurzel: "ġ-n-y / ḥ-m-d", erkl: "„Der Unbedürftige, der Lobenswürdige“ – Allah braucht weder unsere Gebete noch unsere Gaben; und Er ist trotzdem gelobt, weil Er gibt, ohne zu brauchen. Die Doppelformel trennt Gott von jedem Götzen, der Opfer ‚braucht'."},
 {arab: "يَخْشَى", tr: "yachschā", wurzel: "ch-sch-y", erkl: "Ehrfurcht aus Wissen – chaschya ist mehr als chauf (Angst): die Furcht dessen, der die Größe des Gefürchteten kennt. 35:28: „Allah fürchten von Seinen Dienern nur die Wissenden.“ Maßstab echter Bildung."},
 {arab: "سَابِقٌ بِالْخَيْرَات", tr: "sābiqun bi-l-chairāt", wurzel: "s-b-q", erkl: "„Einer, der im Guten vorauseilt“ (35:32) – die dritte und höchste Stufe der Erben des Buches (neben ẓālim li-nafsihī und muqtaṣid). Dieselbe Wurzel wie as-sābiqūn in Al-Wāqiʿa (Lektion 46)."}
],
tafsir: [
 {vers: "Verse 1–8: offene Tür und klare Warnung", text: "Lob des Schöpfers, die Engel mit Flügelpaaren, und 35:2 als Leitvers: Kein Mensch kann zurückhalten, was Allah öffnet. Ibn Kathīr verbindet ihn mit dem Gebet, das der Prophet ﷺ nach jedem Pflichtgebet sprach: „O Allah, niemand hält zurück, was Du gibst, und niemand gibt, was Du zurückhältst“ (Sahih al-Buchari, Nr. 844). Dann die doppelte Warnung: „Das diesseitige Leben soll euch nicht täuschen, und der Täuscher (Satan) soll euch nicht über Allah täuschen“ – und: „Der Satan ist euch ein Feind, so nehmt ihn euch zum Feind“ (35:6). As-Saʿdī: Wer den Satan als Feind behandelt, prüft jeden Gedanken, der zu Sünde einlädt, wie man die Nachricht eines Feindes prüft (vgl. Lektion 21)."},
 {vers: "Verse 9–14: Leben aus totem Land, Kraft der Worte", text: "Der Wind treibt Wolken, totes Land wird belebt – „so ist die Auferstehung“ (vgl. Lektion 34). Dann 35:10: „Wer Macht (ʿizza) will – alle Macht gehört Allah. Zu Ihm steigt das gute Wort auf, und die rechtschaffene Tat erhebt es.“ Al-Qurṭubī: Ehre bei Menschen sucht man vergeblich; wahre ʿizza kommt durch Gehorsam. Und das gute Wort (Dhikr, Wahrheit, gute Rede) steigt auf – getragen von der Tat. Worte ohne Taten bleiben am Boden. Dann der Beweis aus Embryologie, Lebenszeit und Meeren (süß und salzig, beide mit Fisch und Schmuck) – und die Ohnmacht der Götzen: „Sie besitzen nicht einmal das Häutchen eines Dattelkerns (qiṭmīr).“"},
 {vers: "Verse 15–26: Wir sind die Armen", text: "Der Kernvers 35:15 – dann: „Wenn Er will, nimmt Er euch fort und bringt eine neue Schöpfung“ (Allah ist auf keine Generation angewiesen). 35:18 begründet persönliche Verantwortung: „Keine lasttragende (Seele) trägt die Last einer anderen“ (vgl. Lektion 23) – selbst ein Verwandter kann sie nicht abnehmen. Dann die Gleichnisse: Nicht gleich sind der Blinde und der Sehende, Finsternis und Licht, Schatten und Hitze, die Lebenden und die Toten. As-Saʿdī: Der Koran nennt den Gläubigen lebendig, sehend, im Licht und im Schatten – Iman ist Lebensqualität, nicht nur Jenseitsversicherung."},
 {vers: "Verse 27–28: Farben und Ehrfurcht", text: "„Siehst du nicht, dass Allah vom Himmel Wasser herabkommen lässt, und Wir bringen damit Früchte verschiedener Farben hervor? Und in den Bergen gibt es Streifen – weiße und rote, verschiedener Farben – und rabenschwarze. Und unter den Menschen, den Tieren und dem Vieh gibt es ebenso verschiedene Farben. Allah fürchten von Seinen Dienern nur die Wissenden.“ – Bemerkenswert: Der Vers über die ʿulamāʾ steht mitten in einer Beobachtung der Natur und der menschlichen Vielfalt. Ibn Kathīr: Wissende sind die, die Allah kennen – je mehr man Seine Schöpfung versteht, desto größer die Ehrfurcht. Und nebenbei: Die Verschiedenheit der Hautfarben ist im Koran ein Zeichen Allahs, kein Rangmerkmal (vgl. 30:22; 49:13)."},
 {vers: "Verse 29–35: drei Erben des Buches", text: "„Diejenigen, die das Buch Allahs lesen, das Gebet verrichten und von dem, womit Wir sie versorgt haben, heimlich und offen ausgeben, hoffen auf einen Handel, der niemals verloren geht“ (35:29). Dann 35:32: „Dann gaben Wir das Buch denen zum Erbe, die Wir von Unseren Dienern auserwählt haben. Unter ihnen gibt es manche, die sich selbst Unrecht tun, manche, die die Mitte halten, und manche, die mit Allahs Erlaubnis im Guten vorauseilen.“ Ibn Kathīr und as-Saʿdī: Alle drei gehören zur Umma, die das Buch geerbt hat – auch der Sünder ist noch ‚Erbe'; das ist Hoffnung. Aber die Stufen sind real: Pflichten erfüllen und Verbotenes meiden ist die Mitte; Vorauseilen heißt, auch das Empfohlene zu suchen. Die Paradiesbewohner sagen dann: „Lob sei Allah, Der den Kummer von uns genommen hat“ (35:34)."},
 {vers: "Verse 36–45: verspätete Reue und Allahs Geduld", text: "Die Höllenbewohner flehen: „Lass uns heraus, wir wollen Gutes tun!“ – Antwort: „Haben Wir euch nicht so lange leben lassen, dass sich besinnen konnte, wer sich besinnen wollte? Und der Warner kam zu euch“ (35:37). Der Prophet ﷺ erklärte: „Allah lässt keine Entschuldigung mehr gelten für einen Menschen, dessen Lebenszeit Er hinausschob, bis er sechzig Jahre erreichte“ (Sahih al-Buchari, Nr. 6419). Am Ende der Grundsatz von Allahs Geduld: „Würde Allah die Menschen für das belangen, was sie verdient haben, Er ließe auf ihrer Oberfläche kein Lebewesen übrig – doch Er gewährt ihnen Aufschub bis zu einer festgesetzten Frist“ (35:45). Der Aufschub ist Gnade – und Prüfung."}
],
ahadith: [
 {text: "Hadith Qudsi: „O Meine Diener, ihr seid alle irregehend außer dem, den Ich rechtleite – so bittet Mich um Rechtleitung … O Meine Diener, ihr werdet niemals so weit gelangen, Mir zu schaden, noch so weit, Mir zu nützen …“ – der Kommentar der Sunna zu 35:15.", quelle: "Sahih Muslim, Nr. 2577"},
 {text: "Nach jedem Pflichtgebet sprach der Prophet ﷺ: „… O Allah, niemand hält zurück, was Du gibst, und niemand gibt, was Du zurückhältst, und dem Wohlhabenden nützt bei Dir sein Wohlstand nichts.“ – gelebte Fassung von 35:2.", quelle: "Sahih al-Buchari, Nr. 844; Sahih Muslim, Nr. 593"},
 {text: "„Allah lässt keine Entschuldigung mehr gelten für einen Menschen, dessen Frist Er hinausschob, bis er sechzig Jahre erreichte.“ – zu 35:37.", quelle: "Sahih al-Buchari, Nr. 6419"},
 {text: "„Wer einen Weg beschreitet, auf dem er Wissen sucht, dem erleichtert Allah dadurch einen Weg zum Paradies.“ – zu den ʿulamāʾ von 35:28.", quelle: "Sahih Muslim, Nr. 2699"}
],
hanafi: null,
umsetzung: [
 "Sprich nach jedem Pflichtgebet das Gebet von Buchari 844 (allāhumma lā māniʿa limā aʿṭaita …) – damit verankerst du 35:2 fünfmal täglich in deinem Herzen.",
 "Prüfe dein Lernen am Maßstab von 35:28: Macht mich dieses Wissen – auch diese App – ehrfürchtiger, demütiger, gehorsamer? Wenn nicht, hat es sein Ziel noch nicht erreicht.",
 "Ordne dich ehrlich in 35:32 ein: Wo bin ich ẓālim (Pflichten offen), wo muqtaṣid (Pflichten erfüllt), wo sābiq (im Freiwilligen voraus)? Nimm dir EINEN Bereich vor, in dem du eine Stufe aufsteigst.",
 "Wenn Neid oder Existenzangst kommt: „Was Allah öffnet, kann niemand zurückhalten.“ Deine Versorgung ist nicht in der Hand deines Chefs, Konkurrenten oder Neiders.",
 "Ehre die Vielfalt (35:27–28): Rassismus und Herkunftsdünkel widersprechen einem Vers, der verschiedene Hautfarben als Zeichen Allahs feiert."
]
},

// ───────────────────────── Lektion 44: Maryam ─────────────────────────
{
sure: 19, offb: 44, name: "Maryam", arab: "سُورَةُ مَرْيَمَ", de: "Maria", verse: 98, ort: "Mekka",
zeit: "Mittelmekkanisch – vor der ersten Auswanderung nach Abessinien (ca. 615 n. Chr.); vor dem christlichen König rezitiert",
kurz: "Die Sure der Barmherzigkeit: Kein Gottesname kommt in ihr so oft vor wie ar-Raḥmān. Sie erzählt Wunder der Geburt – den greisen Zakariyyā, dem Allah im hohen Alter Yaḥyā schenkt, und Maryam, die ohne Mann ʿĪsā zur Welt bringt, allein unter einer Palme, und deren Neugeborenes in der Wiege spricht: „Ich bin Allahs Diener; Er hat mir die Schrift gegeben und mich zum Propheten gemacht.“ Dann Ibrāhīm, der seinem götzendienenden Vater mit unendlicher Zartheit begegnet („O mein Väterchen …“), und eine Reihe von Propheten, die bei den Versen des Allerbarmers „weinend in Niederwerfung fallen“ (Sadschda-Vers 19:58). Diese Sure rezitierte Dschaʿfar ibn Abī Ṭālib vor dem christlichen König von Abessinien – und der Negus weinte, bis sein Bart nass war.",
schluessel: {arab: "إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَيَجْعَلُ لَهُمُ الرَّحْمَٰنُ وُدًّا", ueb: "Denjenigen, die glauben und rechtschaffene Werke tun, wird der Allerbarmer Liebe bereiten.", ref: "19:96"},
kontext: ["Um 615 n. Chr. war die Verfolgung in Mekka so schlimm geworden, dass der Prophet ﷺ einer Gruppe von Muslimen erlaubte, nach Abessinien auszuwandern – zum christlichen König (Negus/an-Nadschāschī), „bei dem niemandem Unrecht geschieht“. Die Quraisch schickten ʿAmr ibn al-ʿĀṣ mit Geschenken hinterher, um die Auslieferung zu erreichen: Diese Leute würden über ʿĪsā Schlimmes sagen. Der Negus ließ die Muslime rufen. Ihr Sprecher Dschaʿfar ibn Abī Ṭālib erklärte den Islam und rezitierte den Anfang von Sure Maryam. Umm Salama, die dabei war, berichtet: Der Negus weinte, bis sein Bart nass war, seine Bischöfe weinten, bis ihre Schriften nass waren, und er sagte: „Dies und das, was ʿĪsā brachte, kommt aus derselben Nische“ – und verweigerte die Auslieferung (Musnad Aḥmad, Bericht der Umm Salama; von den Hadith-Gelehrten als gut eingestuft).",
"Die Sure zeigt also schon in Mekka, wie der Islam über ʿĪsā und Maryam spricht: mit größter Ehrfurcht (Maryam ist die einzige Frau, nach der eine Sure benannt ist, und wird im Koran öfter erwähnt als im ganzen Neuen Testament) – und mit klarem Tauhīd: ʿĪsā ist Diener und Prophet Allahs, nicht Sein Sohn. „Es ziemt Allah nicht, Sich ein Kind zu nehmen“ (19:35); und gegen Ende die vielleicht schärfste Stelle des Korans zu diesem Thema: „Beinahe brechen die Himmel darüber auseinander, die Erde spaltet sich und die Berge stürzen ein, dass sie dem Allerbarmer ein Kind zuschreiben“ (19:90–91).",
"Für dein Daʿwa-Verständnis wichtig: Die Muslime beschwichtigten vor dem Negus nicht und verwässerten nichts – sie rezitierten genau, was der Koran über ʿĪsā sagt. Und gerade diese Klarheit, verbunden mit Respekt, überzeugte einen ehrlichen Christen. Klarheit und Ehrfurcht sind kein Widerspruch."],
asbab: [
 {text: "Die Rezitation der Sure vor dem Negus durch Dschaʿfar ibn Abī Ṭālib während der Auswanderung nach Abessinien (kein Offenbarungsanlass, sondern ein berühmter Anwendungsfall der bereits offenbarten Sure).", quelle: "Musnad Aḥmad, Bericht der Umm Salama (Nr. 1740); von den Hadith-Gelehrten als hasan eingestuft"},
 {text: "Zu 19:64 („Wir kommen nur auf Befehl deines Herrn herab“): Der Prophet ﷺ fragte Dschibrīl: „Was hindert dich, uns öfter zu besuchen, als du es tust?“ – darauf kam dieser Vers herab.", quelle: "Sahih al-Buchari, Nr. 4731"}
],
begriffe: [
 {arab: "الرَّحْمَٰن", tr: "ar-Raḥmān", wurzel: "r-ḥ-m", erkl: "Der Allerbarmer – in dieser Sure über ein Dutzend Mal, öfter als in jeder anderen. Wo es um Geburt, Kinder, Eltern und Gottes Fürsorge geht, spricht der Koran in der Sprache des Mutterschoßes (raḥim)."},
 {arab: "خَفِيًّا", tr: "chafiyyā", wurzel: "ch-f-y", erkl: "„Im Verborgenen/leise“ (19:3): Zakariyyā rief seinen Herrn „mit leisem Rufen“ an. Die Gelehrten leiten daraus ab: Das stille Duʿā ist näher an Ichlāṣ und Adab – Allah hört auch das Flüstern."},
 {arab: "جِذْع النَّخْلَة", tr: "dschidhʿ an-nachla", wurzel: "dsch-dh-ʿ", erkl: "Der Stamm der Palme (19:23–25): In den Wehen klammert sich Maryam an ihn – und wird angewiesen, ihn zu schütteln, damit frische Datteln fallen. Eine erschöpfte Frau soll einen Palmstamm schütteln? Die Gelehrten: Allah verlangt das Mittel (den Schritt), Er schenkt das Ergebnis."},
 {arab: "يَا أَبَتِ", tr: "yā abati", wurzel: "ʾ-b-w", erkl: "„O mein Väterchen“ (19:42–45) – Ibrāhīm spricht seinen götzendienenden Vater viermal mit dieser zärtlichen Form an. Wahrheit ohne Härte: die Vorlage für jedes Daʿwa-Gespräch mit Eltern."},
 {arab: "سُجَّدًا وَبُكِيًّا", tr: "sudschdschadan wa-bukiyyā", wurzel: "s-dsch-d / b-k-y", erkl: "„Niederwerfend und weinend“ (19:58) – so reagieren die Propheten, wenn ihnen die Verse des Allerbarmers vorgetragen werden. Hier liegt eine der 14 Tilāwa-Sadschdas."},
 {arab: "وُدًّا", tr: "wuddā", wurzel: "w-d-d", erkl: "Liebe, Zuneigung (19:96) – dieselbe Wurzel wie al-Wadūd (Lektion 27). Allah legt den Gläubigen Liebe in die Herzen der Geschöpfe. Echte Beliebtheit ist eine Gabe, keine PR-Leistung."}
],
tafsir: [
 {vers: "Verse 1–15: Zakariyyā und Yaḥyā", text: "Ein alter Mann, „das Haupt glänzt vor Grau“, die Frau unfruchtbar – und er betet trotzdem, leise und voller Vertrauen: „Ich bin mit meinem Gebet zu Dir, mein Herr, nie unglücklich geworden.“ Er fürchtet nicht um sein Erbe, sondern um die Religion nach ihm, und bittet um einen Erben im Glauben. Die Antwort: Yaḥyā – ein Name, den es vorher nicht gab. Als Zeichen soll Zakariyyā drei Nächte nicht sprechen können, obwohl gesund, und morgens und abends Allah preisen. Ibn Kathīr: Lehre für jedes Duʿā – lass dich nie von ‚Unmöglichkeit' abhalten; und bitte zuerst um das, was dem Dīn dient. Über Yaḥyā: „Friede sei auf ihm am Tag, an dem er geboren wurde, am Tag, an dem er stirbt, und am Tag, an dem er wieder zum Leben erweckt wird“ – die drei einsamsten Momente jedes Menschen, von Allah mit Frieden umhüllt."},
 {vers: "Verse 16–40: Maryam und ʿĪsā", text: "Maryam zieht sich zurück, Dschibrīl erscheint ihr als vollkommener Mensch; ihre erste Reaktion ist Zuflucht bei Allah – Keuschheit als Reflex. Die Verkündigung, ihre Frage („Wie soll ich einen Jungen bekommen, wo mich kein Mann berührt hat?“), Allahs Antwort: „Das ist Mir ein Leichtes.“ Dann die Geburt allein unter der Palme, ihr Schmerzensruf („O wäre ich doch vorher gestorben!“ – der Koran verschweigt ihre Not nicht), und der Trost: ein Bach unter ihr, Datteln zum Schütteln, „iss, trink und sei frohen Mutes“. Sie kehrt zu ihrem Volk zurück und gelobt Schweigen – die Anklage: „O Schwester Hārūns, dein Vater war kein schlechter Mann!“ Sie zeigt auf das Kind. Und das Kind spricht: „Ich bin Allahs Diener …“ Die erste Selbstbeschreibung ʿĪsās im Koran ist ʿabdullāh – Diener Allahs. Dann 19:34–36 klärt die Streitfrage über ihn: „Das ist ʿĪsā, der Sohn Maryams – das Wort der Wahrheit, über das sie zweifeln. Es ziemt Allah nicht, Sich ein Kind zu nehmen … Allah ist mein Herr und euer Herr, so dient Ihm.“"},
 {vers: "Verse 41–50: Ibrāhīm und sein Vater", text: "Viermal „yā abati“ – Ibrāhīm argumentiert sanft: Warum dienst du dem, was nicht hört und nicht sieht? Mir ist Wissen zugekommen, das dir nicht zukam – folge mir, ich führe dich einen ebenen Weg. Der Vater droht mit Steinigung und Verstoßung. Ibrāhīms Antwort ist ein Meisterwerk: „Friede sei auf dir! Ich werde meinen Herrn für dich um Vergebung bitten.“ As-Saʿdī: Er antwortet auf die Drohung mit salām und Duʿā – der Höhepunkt des Adab gegenüber Eltern, selbst wenn sie den Dīn bekämpfen (vgl. 31:15: im Diesseits in rechtlicher Weise mit ihnen umgehen). Er geht – und Allah schenkt ihm Isḥāq und Yaʿqūb: Wer für Allah etwas verlässt, dem ersetzt Allah es mit Besserem."},
 {vers: "Verse 51–65: die Prophetenreihe und die Sadschda", text: "Mūsā („aufrichtig erwählt“, im Zwiegespräch nahegebracht), Ismāʿīl („wahrhaftig im Versprechen“, der seiner Familie Gebet und Zakat gebot), Idrīs („an einen hohen Ort erhoben“). Dann 19:58: „Das sind diejenigen, denen Allah Gunst erwiesen hat unter den Propheten … Wenn ihnen die Verse des Allerbarmers verlesen wurden, fielen sie weinend in Niederwerfung.“ Und sofort der Kontrast 19:59: „Nach ihnen folgten Nachfolger, die das Gebet vernachlässigten (aḍāʿū ṣ-ṣalāh) und den Begierden folgten – sie werden ins Verderben (ġayy) geraten, außer wer bereut.“ Ibn Masʿūd und andere: ‚Vernachlässigen' heißt hier vor allem, das Gebet aus seiner Zeit zu schieben – nicht unbedingt, es ganz zu lassen (vgl. Lektion 17). Dann 19:64 (Anlass oben): Dschibrīl kommt nur auf Allahs Befehl."},
 {vers: "Verse 66–98: Auferstehung, ‚Kind' und Liebe", text: "Der Zweifler fragt: „Wenn ich gestorben bin, werde ich dann wirklich lebendig hervorgebracht?“ – „Erinnert sich der Mensch nicht, dass Wir ihn zuvor erschufen, als er nichts war?“ 19:71–72: „Es gibt keinen unter euch, der nicht zu ihr (der Hölle) hinkäme … dann retten Wir die Gottesfürchtigen“ – nach den Mufassirūn das Überqueren der Brücke (ṣirāṭ) über ihr. Dann die Arroganz dessen, der sagt „Mir werden gewiss Vermögen und Kinder gegeben“ (Anlass: al-ʿĀṣ ibn Wāʾil gegenüber Chabbāb – Sahih al-Buchari, Nr. 4732). Schließlich der Donner von 19:88–95 gegen die Zuschreibung eines Kindes: „Niemand in den Himmeln und auf der Erde wird anders zum Allerbarmer kommen als als Diener.“ Und das sanfte Ende: 19:96 – Liebe für die Gläubigen – und 19:97: „Wir haben ihn (den Koran) leicht gemacht in deiner Sprache“ (vgl. Lektion 37)."}
],
ahadith: [
 {text: "„Wenn Allah einen Diener liebt, ruft Er Dschibrīl: Allah liebt den Soundso, so liebe ihn! Dann liebt ihn Dschibrīl und ruft den Himmelsbewohnern zu … dann wird ihm auf der Erde Annahme gegeben.“ – der Kommentar zu 19:96.", quelle: "Sahih al-Buchari, Nr. 3209; Sahih Muslim, Nr. 2637"},
 {text: "Der Tod wird am Tag der Auferstehung in Gestalt eines Widders gebracht und zwischen Paradies und Hölle geschlachtet; dann wird gerufen: „Ewigkeit, kein Tod mehr!“ – und der Prophet ﷺ rezitierte 19:39 („Und warne sie vor dem Tag des Bedauerns …“).", quelle: "Sahih al-Buchari, Nr. 4730; Sahih Muslim, Nr. 2849"},
 {text: "„Wer bezeugt, dass es keinen Gott gibt außer Allah … und dass ʿĪsā Allahs Diener und Gesandter ist, Sein Wort, das Er Maryam entbot, und ein Geist von Ihm …, den lässt Allah ins Paradies eintreten.“", quelle: "Sahih al-Buchari, Nr. 3435; Sahih Muslim, Nr. 28"},
 {text: "Der Prophet ﷺ fragte Dschibrīl, warum er nicht öfter komme – darauf wurde 19:64 herabgesandt.", quelle: "Sahih al-Buchari, Nr. 4731"}
],
hanafi: "19:58 ist eine Sadschda-Stelle: Nach hanafitischer Schule ist die Rezitations-Niederwerfung beim Lesen oder Hören dieses Verses wādschib (vgl. Lektion 1). Die Sunna des Verses selbst zeigt die Haltung: Takbīr, Niederwerfung – und wenn möglich mit innerer Rührung („weinend“). Zweiter Punkt aus 19:59: Das Hinausschieben des Gebets aus seiner Zeit ohne gültigen Grund ist nach der Schule eine schwere Sünde; versäumte Gebete müssen nachgeholt werden (qaḍāʾ).",
umsetzung: [
 "Lerne das stille Duʿā von Zakariyyā (19:3–6): Nimm dir eine ‚unmögliche' Bitte und trage sie Allah leise, regelmäßig und ohne Verzweiflung vor – „mit meinem Gebet zu Dir bin ich nie unglücklich geworden“.",
 "Übe yā abati: Wenn deine Eltern anders denken als du (religiös oder sonst), sprich mit ihnen nur noch in Ibrāhīms Ton – sanft, respektvoll, mit Duʿā statt Diskussion um jeden Preis.",
 "Mach bei 19:58 die Tilāwa-Sadschda (hanafitisch wādschib) – und versuche einmal, die Verse davor so langsam zu lesen, dass dein Herz mitgeht.",
 "Für Gespräche mit Christen: Lerne 19:30–36 auf Deutsch. Es ist die Stelle, mit der Dschaʿfar den Negus erreichte – ehrfürchtig über ʿĪsā und Maryam, klar im Tauhīd.",
 "Nimm 19:96 als Beziehungsregel: Arbeite an Iman und guten Taten, nicht an deinem Image. Die Liebe der Menschen ist Allahs Geschenk an die Seinen."
]
},

// ───────────────────────── Lektion 45: Ṭā-Hā ─────────────────────────
{
sure: 20, offb: 45, name: "Ṭā-Hā", arab: "سُورَةُ طه", de: "Ṭā-Hā", verse: 135, ort: "Mekka",
zeit: "Mittelmekkanisch – kurz vor dem Islam ʿUmar ibn al-Chaṭṭābs (ca. 616 n. Chr.)",
kurz: "„Wir haben den Koran nicht auf dich herabgesandt, damit du unglücklich wirst“ – so beginnt die Sure, die ʿUmar ibn al-Chaṭṭāb zum Islam brachte. Ihr Hauptteil ist die ausführlichste Mūsā-Erzählung des Korans: die Feuer-Begegnung im Tal Ṭuwā („Ich bin Allah … so diene Mir und verrichte das Gebet zu Meinem Gedenken“), die Kindheit im Kästchen auf dem Nil, die Mission zu Pharao mit dem Auftrag, „mild zu ihm zu sprechen“, das Zauberer-Duell, der Auszug – und das goldene Kalb des Sāmirī. Dann Ādam, der vergaß, und die zentrale Warnung: „Wer sich von Meiner Ermahnung abwendet, der wird ein beengtes Leben führen.“ Mittendrin das schönste Lerner-Gebet des Korans: „Mein Herr, mehre mir Wissen.“",
schluessel: {arab: "مَا أَنزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَىٰ", ueb: "Wir haben den Koran nicht auf dich herabgesandt, damit du unglücklich wirst.", ref: "20:2"},
kontext: ["Der berühmteste Bericht zu dieser Sure stammt aus der Sīra (Ibn Isḥāq u. a.; nicht in Buchari/Muslim): ʿUmar ibn al-Chaṭṭāb zog mit dem Schwert los, um den Propheten ﷺ zu töten. Unterwegs erfuhr er, dass seine eigene Schwester Fāṭima und ihr Mann Saʿīd Muslime geworden waren. Er stürmte in ihr Haus, wo Chabbāb ihnen gerade Ṭā-Hā lehrte, schlug seine Schwester blutig – und als er das Blut sah, verlangte er das Blatt. Sie forderte ihn auf, sich erst zu waschen. Er las den Anfang von Ṭā-Hā und sagte: „Wie schön und wie edel ist diese Rede!“ Dann ging er zum Propheten ﷺ ins Haus des al-Arqam und nahm den Islam an. Ibn Masʿūd sagte später: „Wir waren stark, seit ʿUmar Muslim wurde“ (Sahih al-Buchari, Nr. 3684).",
"Der Eröffnungsvers 20:2 ist eine Antwort auf die Last, die der Prophet ﷺ trug: Er betete nachts bis zur Erschöpfung und litt unter der Ablehnung. Allah sagt: Dieser Koran ist keine Strafe, sondern „eine Erinnerung für den, der (Allah) fürchtet“. Religion soll den Menschen nicht zerbrechen, sondern aufrichten – eine wichtige Botschaft gegen religiösen Perfektionismus und Selbstquälerei.",
"Die Mūsā-Geschichte ist hier auf die Seelsorge des Propheten ﷺ zugeschnitten: Auch Mūsā hatte Angst (vor Pharao, vor den Schlangen der Zauberer), auch er bat um Hilfe (Hārūn als Unterstützer), auch sein Volk fiel nach der Rettung zurück. Die Botschaft an den Propheten ﷺ und an dich: Allah war mit Mūsā – „Ich bin mit euch beiden; Ich höre und sehe“ (20:46) – Er ist auch mit dir."],
asbab: ["Für die Sure als Ganze ist kein einzelner Offenbarungsanlass sahih überliefert. Die verbreitete Erklärung zu 20:2 (der Prophet ﷺ habe nachts bis zur Erschöpfung gebetet, die Gegner hätten gesagt, der Koran mache ihn unglücklich) findet sich in der Tafsir-Literatur, aber nicht mit gesicherter Kette. Die Geschichte von ʿUmars Islam bei der Lektüre dieser Sure stammt aus der Sīra (Ibn Isḥāq), nicht aus den Sahih-Werken."],
begriffe: [
 {arab: "لِتَشْقَىٰ", tr: "li-taschqā", wurzel: "sch-q-w", erkl: "„Damit du unglücklich/geplagt wirst“ (20:2) – schaqāʾ ist das Gegenteil von saʿāda (Glück). Der Koran wurde nicht zur Qual herabgesandt. Wer Religion als Dauerstress erlebt, hat etwas missverstanden."},
 {arab: "لِذِكْرِي", tr: "li-dhikrī", wurzel: "dh-k-r", erkl: "„… und verrichte das Gebet zu Meinem Gedenken“ (20:14) – der Sinn des Gebets in einem Wort: Allah gedenken. Der Prophet ﷺ zitierte genau diesen Vers bei der Regel, dass ein vergessenes Gebet nachgeholt wird, sobald man sich erinnert."},
 {arab: "قَوْلًا لَّيِّنًا", tr: "qaulan layyinā", wurzel: "l-y-n", erkl: "„Mildes Wort“ (20:44): Mūsā und Hārūn sollen sogar zum schlimmsten Tyrannen der Geschichte „mild sprechen – vielleicht lässt er sich ermahnen oder fürchtet sich“. Wenn sanfte Rede für Pharao gilt – wie viel mehr für deine Geschwister im Glauben."},
 {arab: "السَّامِرِيّ", tr: "as-Sāmirī", wurzel: "s-m-r", erkl: "Der Mann, der in Mūsās Abwesenheit das goldene Kalb formte – der Prototyp des religiösen Verführers, der Gefühle (glänzendes Gold, ein ‚muhender' Klang) statt Wahrheit anbietet. Seine Strafe: lebenslange Isolation („Rühr mich nicht an“)."},
 {arab: "رَبِّ زِدْنِي عِلْمًا", tr: "rabbi zidnī ʿilmā", wurzel: "z-y-d / ʿ-l-m", erkl: "„Mein Herr, mehre mir Wissen“ (20:114) – das einzige Mehr, um das der Prophet ﷺ im Koran ausdrücklich bitten soll. Das Gebet jedes Lernenden – auch deins, bevor du eine Lektion öffnest."},
 {arab: "مَعِيشَةً ضَنكًا", tr: "maʿīschatan ḍankā", wurzel: "ḍ-n-k", erkl: "„Ein beengtes Leben“ (20:124) – wer sich vom Gedenken abwendet, lebt eng: nach den Mufassirūn innere Enge, Unruhe, Leere – auch bei äußerem Reichtum – und die Enge des Grabes. Die koranische Diagnose von Sinnkrise."}
],
tafsir: [
 {vers: "Verse 1–8: kein Unglück, sondern Erinnerung", text: "Ṭā-Hā (Einzelbuchstaben, vgl. Lektion 2), dann der Trost 20:2, dann die Herkunft des Korans: „von Dem, Der die Erde und die hohen Himmel erschaffen hat. Der Allerbarmer hat sich über den Thron erhoben (istawā).“ Die Ahl as-Sunna bestätigen dieses Erheben, wie es Allahs Majestät gebührt, ohne es mit Geschöpflichem zu vergleichen und ohne nach dem Wie zu fragen – so die berühmte Antwort Imām Māliks: „Das Erheben ist bekannt, das Wie ist unbekannt, daran zu glauben ist Pflicht, danach zu fragen ist Neuerung.“ Vers 7: „Er kennt das Geheime und das noch Verborgenere“ – sogar was du noch nicht einmal dir selbst eingestanden hast."},
 {vers: "Verse 9–48: Berufung am Feuer", text: "Mūsā, auf dem Rückweg aus Madyan, sieht in kalter Nacht ein Feuer und will Glut oder Wegweisung holen – und findet beides: „Ich bin dein Herr, zieh deine Sandalen aus, du bist im heiligen Tal Ṭuwā.“ Die drei Kernsätze: Tauhīd („Ich bin Allah, es gibt keinen Gott außer Mir“), Gebet („verrichte das Gebet zu Meinem Gedenken“), Jenseits („die Stunde kommt“). Dann die Zeichen (Stab und Hand) und Mūsās Bitte, die jeder vor einer schweren Aufgabe sprechen sollte: „Mein Herr, weite mir meine Brust, erleichtere mir meine Angelegenheit, löse den Knoten meiner Zunge, damit sie mein Wort verstehen, und gib mir einen Helfer aus meiner Familie“ (20:25–29, vgl. Lektion 12). Allah erinnert ihn an Seine frühere Fürsorge: das Kästchen auf dem Nil, die Rückkehr zur Mutter („damit ihr Auge sich freue“), die Zeit in Madyan – „Ich habe dich für Mich ausgewählt.“ Und 20:44: zu Pharao mild sprechen."},
 {vers: "Verse 49–76: Pharao und die Zauberer", text: "Pharaos Frage: „Wer ist euer Herr?“ – Mūsās Antwort: „Unser Herr ist Der, Der jedem Ding seine Gestalt gab und es dann rechtleitete“ (vgl. Lektion 8). Das Duell wird auf den Festtag gelegt, „wenn die Menschen am Vormittag versammelt sind“ – Mūsā wählt die maximale Öffentlichkeit. Die Zauberer werfen ihre Stricke, die sich zu bewegen scheinen, und „Mūsā fühlte in seiner Seele Angst“ – der Koran verschweigt die Angst der Propheten nicht. „Fürchte dich nicht, du bist der Überlegene.“ Der Stab verschlingt ihr Machwerk, und die Zauberer werfen sich nieder: „Wir glauben an den Herrn Hārūns und Mūsās.“ Pharao droht mit Kreuzigung und Verstümmelung. Ihre Antwort (20:72) gehört zu den stärksten Sätzen der Glaubensgeschichte: „Entscheide, was du entscheiden willst – du entscheidest nur über dieses diesseitige Leben.“ Morgens Zauberer, abends Märtyrer – Ibn ʿAbbās. Wahrheit, einmal erkannt, kann ein Herz in Minuten verwandeln."},
 {vers: "Verse 77–98: Auszug und goldenes Kalb", text: "Rettung durchs Meer, Pharaos Untergang, die Gaben in der Wüste. Dann geht Mūsā zur Verabredung mit Allah voraus, und in seiner Abwesenheit formt der Sāmirī aus dem Schmuck ein Kalb „mit Muhen“ – und das Volk sagt: „Das ist euer Gott und der Gott Mūsās – er hat es (nur) vergessen.“ Hārūn warnt vergeblich. Mūsā kehrt zornig zurück, packt seinen Bruder am Bart, und Hārūn bittet: „O Sohn meiner Mutter … ich fürchtete, du würdest sagen: Du hast Spaltung unter die Kinder Israels gebracht.“ Al-Qurṭubī: Hārūn wählte, die Einheit nicht zu zerreißen, bis Mūsā zurückkehrt – eine Lehre über Abwägung zwischen Wahrheit und Einheit. Der Sāmirī wird ausgestoßen, das Kalb verbrannt und ins Meer gestreut: „Euer Gott ist nur Allah, außer Dem es keinen Gott gibt; Er umfasst alles mit Wissen.“"},
 {vers: "Verse 99–114: Tag der Auferstehung und das Lerner-Gebet", text: "Die Berge werden zu Staub, die Erde eine ebene Fläche, „keine Krümmung und keine Erhebung“; die Stimmen „gesenkt vor dem Allerbarmer, du hörst nur ein Flüstern“. Dann zum Koran-Empfang: „Übereile dich nicht mit dem Koran, bevor seine Offenbarung an dich vollendet ist, und sag: Mein Herr, mehre mir Wissen“ (20:114) – dieselbe Lehre wie 75:16 (Lektion 31): erst zuhören, dann wiedergeben, und um Wachstum bitten."},
 {vers: "Verse 115–135: Ādam, Vergessen und Geduld", text: "„Wir hatten Ādam zuvor ein Versprechen auferlegt, doch er vergaß – und Wir fanden bei ihm keine Entschlossenheit (ʿazm).“ Iblīs flüstert: „Soll ich dich auf den Baum der Ewigkeit hinweisen und zu einer Herrschaft, die nicht vergeht?“ – die Versuchung arbeitet mit dem Wunsch nach Unsterblichkeit und Macht (vgl. 104:3, Lektion 32). Ādam fällt, bereut, und „sein Herr erwählte ihn, wandte sich ihm zu und leitete ihn“. Dann die zwei Wege: „Wer Meiner Rechtleitung folgt, geht nicht irre und wird nicht unglücklich“ (das Gegenwort zu li-taschqā aus Vers 2 – die Sure schließt ihren Kreis) – „wer sich von Meiner Ermahnung abwendet, dem wird ein beengtes Leben zuteil, und Wir versammeln ihn am Tag der Auferstehung blind.“ Schluss: Geduld mit dem Gerede, Tasbīḥ vor Sonnenauf- und -untergang (vgl. Lektion 31), „richte deine Augen nicht auf das, was Wir manchen zum Genuss gegeben haben“, und „gebiete deiner Familie das Gebet und sei beharrlich darin“ (20:132)."}
],
ahadith: [
 {text: "„Wer ein Gebet vergisst, soll es beten, wenn er sich daran erinnert – es gibt keine Sühne dafür außer dieser.“ Und er rezitierte: „… und verrichte das Gebet zu Meinem Gedenken“ (20:14).", quelle: "Sahih al-Buchari, Nr. 597; Sahih Muslim, Nr. 684"},
 {text: "Das Streitgespräch zwischen Ādam und Mūsā: „Du bist Ādam, der die Menschen aus dem Paradies brachte?“ – „Du tadelst mich für etwas, das Allah über mich bestimmte, bevor Er mich erschuf?“ – „So besiegte Ādam Mūsā (im Argument).“ Die Gelehrten: Es ging um das Unglück (die Folge), nicht um die Rechtfertigung der Sünde, die Ādam längst bereut hatte.", quelle: "Sahih al-Buchari, Nr. 3409; Sahih Muslim, Nr. 2652"},
 {text: "Ibn Masʿūd: „Wir waren stark, seit ʿUmar den Islam angenommen hat.“", quelle: "Sahih al-Buchari, Nr. 3684"},
 {text: "„Gebietet euren Kindern das Gebet, wenn sie sieben Jahre alt sind …“ – Umsetzung von 20:132 in der Familie.", quelle: "Sunan Abū Dāwūd, Nr. 495; hasan"}
],
hanafi: "Zu 20:14 und dem Hadith über vergessene Gebete gilt hanafitisch: Versäumte Pflichtgebete (und das wādschib-Witr) müssen nachgeholt werden (qaḍāʾ), egal ob durch Vergessen, Schlaf oder Nachlässigkeit. Besonderheit der Schule ist die Reihenfolge (tartīb): Wer insgesamt weniger als sechs versäumte Gebete offen hat (ṣāḥib at-tartīb), muss diese in der richtigen Reihenfolge und VOR dem aktuellen Gebet nachholen, sofern die Zeit reicht. Wer sechs oder mehr offen hat, für den entfällt die Reihenfolgepflicht. Praktisch: Versäumtes sofort nachholen – das hält dich im Status des Leichten.",
umsetzung: [
 "Sprich vor jeder Lerneinheit rabbi zidnī ʿilmā (20:114) – und vor jeder schweren Aufgabe Mūsās Gebet rabbi schraḥ lī ṣadrī … (20:25–28).",
 "Hol offene Gebete nach – heute, nicht ‚irgendwann'. Wenn es viele sind: pro Pflichtgebet ein qaḍāʾ dazu, bis die Liste leer ist.",
 "Übe qaulan layyinā (20:44): Wähle das schwierigste Gespräch dieser Woche und führe es bewusst mild. Wenn Pharao Milde verdient hat, verdient dein Gegenüber sie erst recht.",
 "Prüfe dich auf maʿīscha ḍanka (20:124): Wo fühlst du innere Enge trotz äußerer Fülle? Das ist laut Koran ein Dhikr-Mangel – behandle ihn mit festen Gedenkzeiten.",
 "Setze 20:132 in deiner Familie um: Das Gebet anstoßen, beharrlich und freundlich – auch bei Geschwistern, Ehepartner, Kindern."
]
},

// ───────────────────────── Lektion 46: Al-Wāqiʿa ─────────────────────────
{
sure: 56, offb: 46, name: "Al-Wāqiʿa", arab: "سُورَةُ الْوَاقِعَةِ", de: "Das Eintreffende", verse: 96, ort: "Mekka",
zeit: "Mittelmekkanisch – eine der Suren, die den Propheten ﷺ ‚grau werden ließen'",
kurz: "„Wenn das Eintreffende eintrifft – sein Eintreffen kann niemand leugnen –, erniedrigend, erhöhend!“ Die Sure teilt die Menschheit am Jüngsten Tag in drei Gruppen: die Gefährten der Rechten, die Gefährten der Linken – und die Vordersten (as-sābiqūn), die Allah am nächsten gebracht werden. Sie beschreibt die Belohnung der Vordersten und der Rechten in den sinnlichsten Bildern des Korans und die Strafe der Linken in den härtesten. Dann vier Fragen, die jeden Alltag verwandeln: Der Same, den ihr ergießt – erschafft IHR ihn? Die Saat, die ihr sät – lasst IHR sie wachsen? Das Wasser, das ihr trinkt – sendet IHR es herab? Das Feuer, das ihr entfacht – habt IHR seinen Baum entstehen lassen? Und am Ende die Sterbestunde, wenn die Seele die Kehle erreicht – und die Frage: Zu welcher der drei Gruppen gehörst du?",
schluessel: {arab: "وَالسَّابِقُونَ السَّابِقُونَ ۝ أُولَٰئِكَ الْمُقَرَّبُونَ", ueb: "Und die Vordersten, ja, die Vordersten – das sind die (Allah) Nahegebrachten.", ref: "56:10–11"},
kontext: ["Abū Bakr sagte zum Propheten ﷺ: „O Gesandter Allahs, du bist grau geworden!“ Er antwortete: „Hūd, al-Wāqiʿa, al-Mursalāt, ʿAmma yatasāʾalūn und Idhā sch-schamsu kuwwirat haben mich grau werden lassen“ (Sunan at-Tirmidhī, Nr. 3297; hasan). Diese Sure gehört also zu den Texten, deren Ernst den Propheten ﷺ körperlich zeichnete.",
"Al-Wāqiʿa ist um eine einzige Frage gebaut: Wo stehst du? Sie beginnt mit der großen Sortierung (Verse 1–56), legt dann die Beweise auf den Tisch, die jeder täglich sieht (57–74), schwört bei den Positionen der Sterne auf die Echtheit des Korans (75–82) – und endet im Sterbezimmer, wo die Sortierung für jeden Einzelnen Wirklichkeit wird (83–96). Drei Gruppen am Anfang, drei Gruppen am Ende: Die Sure ist wie ein Kreis um dein eigenes Leben gezogen.",
"Ehrlich zu einem bekannten Vorzug: Der verbreitete Hadith „Wer al-Wāqiʿa jede Nacht rezitiert, den trifft niemals Armut“ ist nach dem Urteil der Hadith-Kritiker schwach (ḍaʿīf; überliefert u. a. bei al-Baihaqī, Schuʿab al-Īmān). Viele Muslime lesen sie trotzdem jeden Abend – und das ist gut, denn ihr Inhalt verdient es; nur sollte man den schwachen Hadith nicht als gesicherte Garantie weitergeben (vgl. die Einordnung bei Yā-Sīn, Lektion 41)."],
asbab: [
 {text: "Zu 56:75–82 („Ich schwöre bei den Standorten der Sterne … und macht ihr eure Versorgung zum Leugnen?“): Ibn ʿAbbās berichtet, es habe zur Zeit des Propheten ﷺ geregnet, und manche sagten, der Regen komme durch den Stern Soundso – daraufhin kamen diese Verse herab.", quelle: "Sahih Muslim, Nr. 73"}
],
begriffe: [
 {arab: "الْوَاقِعَة", tr: "al-wāqiʿa", wurzel: "w-q-ʿ", erkl: "„Das Eintreffende“ – ein Name des Jüngsten Tages: das Ereignis, das so sicher fällt wie ein Stein, der aufschlägt (waqaʿa: fallen, sich ereignen). Es ist nicht ‚vielleicht', sondern schon so gut wie geschehen."},
 {arab: "خَافِضَةٌ رَّافِعَةٌ", tr: "chāfiḍatun rāfiʿa", wurzel: "ch-f-ḍ / r-f-ʿ", erkl: "„Erniedrigend, erhöhend“ (56:3): Der Tag stellt die Rangordnung auf den Kopf – Mächtige der Dunya werden erniedrigt, Unbeachtete erhöht (vgl. ʿAbasa, Lektion 24)."},
 {arab: "السَّابِقُون", tr: "as-sābiqūn", wurzel: "s-b-q", erkl: "„Die Vordersten“ – die im Guten vorauseilen (vgl. 35:32 in Lektion 43): die ersten Gläubigen, die ersten zum Gebet, die ersten bei jeder guten Tat. „Viele von den Früheren und wenige von den Späteren“ (56:13–14) – je später die Zeit, desto seltener."},
 {arab: "الْمُقَرَّبُون", tr: "al-muqarrabūn", wurzel: "q-r-b", erkl: "„Die Nahegebrachten“ – die höchste Stufe: nicht nur im Paradies, sondern in Allahs Nähe. Nähe ist das eigentliche Ziel der Tazkiya – die Gärten sind die Folge."},
 {arab: "أَفَرَأَيْتُم", tr: "a-fa-raʾaitum", wurzel: "r-ʾ-y", erkl: "„Habt ihr gesehen …?“ – viermal (56:58, 63, 68, 71): der Same, die Saat, das Wasser, das Feuer. Der Koran zeigt auf die gewöhnlichsten Dinge und fragt: Wer macht das eigentlich? Dankbarkeit beginnt mit Hinschauen."},
 {arab: "الْمُطَهَّرُون", tr: "al-muṭahharūn", wurzel: "ṭ-h-r", erkl: "„Die Gereinigten“ (56:79): „das nur die Gereinigten berühren“ – im ersten Sinn die Engel, die die himmlische Urschrift berühren; die Gelehrten leiten daraus (mit der Sunna) die Regel ab, den Mushaf nur in Reinheit zu berühren."}
],
tafsir: [
 {vers: "Verse 1–26: die Vordersten", text: "Die Erde wird erschüttert, die Berge zerbröselt zu verstreutem Staub – und die Menschen sind „drei Arten“. Zuerst die Vordersten, „in den Gärten der Wonne“, auf golddurchwirkten Liegen einander gegenüber (keiner dreht dem anderen den Rücken – Gemeinschaft ohne Groll), umkreist von ewig jungen Dienern mit Bechern aus reinem Quell, „von dem sie weder Kopfweh bekommen noch sich berauschen“, Früchte nach Wahl, Geflügelfleisch nach Begehr, Ḥūr wie wohlverwahrte Perlen – „als Lohn für das, was sie zu tun pflegten“. Und das Schönste zuletzt: „Sie hören darin weder leeres Gerede noch Sündhaftes – nur das Wort: Friede, Friede (salāman salāmā).“ As-Saʿdī: Die Freuden des Paradieses sind Belohnung für die Selbstbeherrschung im Diesseits – wer hier auf Rausch, leeres Gerede und Verbotenes verzichtet, bekommt dort die reine Form davon."},
 {vers: "Verse 27–56: Rechte und Linke", text: "Die Gefährten der Rechten: dornlose Lotusbäume, gestaffelte Bananenstauden, ausgedehnter Schatten, fließendes Wasser, Früchte, „die weder aufhören noch verwehrt werden“. „Eine Schar von den Früheren und eine Schar von den Späteren“ (56:39–40) – hier ist auch für die späteren Generationen viel Raum. Dann die Linke: Glutwind, siedendes Wasser, Schatten aus schwarzem Rauch, „weder kühl noch angenehm“. Ihr Vergehen wird präzise benannt: „Sie lebten vorher im Wohlstand (mutrafīn), verharrten in der gewaltigen Sünde und sagten: Wenn wir gestorben sind … werden wir dann wirklich auferweckt?“ Al-Qurṭubī: Luxus ohne Dankbarkeit, Beharren statt Reue, Leugnung des Jenseits – die drei Merkmale der linken Seite."},
 {vers: "Verse 57–74: vier Fragen für den Alltag", text: "„WIR haben euch erschaffen – warum haltet ihr es nicht für wahr?“ Dann die vier Fragen: Der Same – erschafft ihr ihn oder Wir? Die Saat – lasst ihr sie wachsen oder Wir? („Wollten Wir, Wir machten sie zu zerbröckeltem Zeug“ – jede Missernte ist eine Erinnerung.) Das Trinkwasser – sendet ihr es aus den Wolken oder Wir? („Wollten Wir, Wir machten es salzig – warum seid ihr nicht dankbar?“) Das Feuer – habt ihr seinen Baum entstehen lassen oder Wir? („Wir haben es zu einer Erinnerung gemacht und zu einem Nutzen für die Reisenden in der Wüste.“) Ibn Kathīr: Vier Grundbedürfnisse – Nachkommen, Nahrung, Wasser, Energie – und keines davon hat der Mensch wirklich ‚gemacht'. Daraus folgt nur eines: „So preise den Namen deines gewaltigen Herrn“ (56:74). Der Prophet ﷺ ordnete an: „Macht es in eure Verbeugung“ – daher subḥāna rabbiya l-ʿaẓīm im Rukūʿ (Sunan Abū Dāwūd, Nr. 869; vgl. Lektion 8)."},
 {vers: "Verse 75–82: Schwur bei den Sternen", text: "„Ich schwöre bei den Standorten der Sterne – und das ist, wenn ihr es nur wüsstet, ein gewaltiger Schwur –, dies ist wahrlich ein edler Koran, in einem wohlverwahrten Buch, das nur die Gereinigten berühren, eine Herabsendung vom Herrn der Welten.“ Dann der Vorwurf: „Macht ihr eure Versorgung zum Leugnen?“ – nach dem Anlass (Muslim 73) ist gemeint: Regen bekommen und ihn den Sternen statt Allah zuschreiben. Übertragen auf heute: jede Gabe einem ‚System', ‚Glück' oder ‚Zufall' zuschreiben statt dem Geber."},
 {vers: "Verse 83–96: die Sterbestunde", text: "„Warum nicht – wenn sie (die Seele) die Kehle erreicht und ihr in jenem Augenblick zuschaut – und Wir ihm näher sind als ihr, doch ihr seht es nicht –, warum holt ihr sie dann nicht zurück, wenn ihr (angeblich) keiner Abrechnung unterworfen seid?“ Das stärkste Argument gegen den Materialismus: Niemand kann einen Sterbenden zurückhalten. Dann noch einmal die drei Gruppen, jetzt im Moment des Todes: Für den Nahegebrachten „Ruhe, Duft und ein Garten der Wonne“; für den der Rechten der Gruß „Friede dir von den Gefährten der Rechten“; für den Leugner „siedendes Wasser und Brennen im Höllenfeuer“. Schluss: „Dies ist wahrlich die gewisse Wahrheit (ḥaqq al-yaqīn). So preise den Namen deines gewaltigen Herrn.“"}
],
ahadith: [
 {text: "„Hūd, al-Wāqiʿa, al-Mursalāt, ʿAmma yatasāʾalūn und Idhā sch-schamsu kuwwirat haben mich grau werden lassen.“", quelle: "Sunan at-Tirmidhī, Nr. 3297; hasan"},
 {text: "Hadith Qudsi nach einer regnerischen Nacht: „Unter Meinen Dienern sind heute Morgen Gläubige an Mich und Ungläubige. Wer sagt: Wir haben Regen durch Allahs Huld und Barmherzigkeit – der glaubt an Mich … Wer sagt: Durch den Stern Soundso – der glaubt an den Stern.“", quelle: "Sahih al-Buchari, Nr. 846; Sahih Muslim, Nr. 71"},
 {text: "Ibn ʿAbbās zum Anlass von 56:75–82 (Regen, der den Sternen zugeschrieben wurde).", quelle: "Sahih Muslim, Nr. 73"},
 {text: "„Im Paradies gibt es einen Baum, in dessen Schatten ein Reiter hundert Jahre reitet, ohne ihn zu durchqueren. Lest, wenn ihr wollt: ‚und ausgedehnter Schatten' (56:30).“", quelle: "Sahih al-Buchari, Nr. 4881; Sahih Muslim, Nr. 2826"}
],
hanafi: "Zu 56:79 („das nur die Gereinigten berühren“) gilt nach hanafitischer Schule (wie in Lektion 24 erklärt): Den Mushaf ohne Wudū zu berühren ist nicht erlaubt; ein Ǧunub (im Zustand großer Unreinheit) darf zudem nicht rezitieren. Tragen in einer separaten Hülle ist erlaubt. Gestützt wird die Regel auch durch das Schreiben des Propheten ﷺ an ʿAmr ibn Ḥazm: „Niemand berühre den Koran außer ein Reiner“ (Muwaṭṭaʾ Mālik, Buch des Korans). Praktisch zu 56:74 und 56:96: subḥāna rabbiya l-ʿaẓīm im Rukūʿ ist hanafitisch Sunna, mindestens dreimal.",
umsetzung: [
 "Stelle dir die Drei-Gruppen-Frage jeden Abend: Hat mich dieser Tag näher zu den Vordersten, zu den Rechten – oder zu den Linken gebracht? Al-Wāqiʿa abends zu lesen ist eine gute Gewohnheit, auch ohne den schwachen Armuts-Hadith.",
 "Mach die vier a-fa-raʾaitum-Übungen konkret: beim Essen (Saat), beim Trinken (Wasser), beim Heizen/Kochen (Feuer), beim Blick auf Kinder (Same) – jedes Mal innerlich: „Nicht ich, sondern Er.“",
 "Sag bei Regen und jeder Gabe muṭirnā bi-faḍli llāhi wa-raḥmatih (Wir bekamen Regen durch Allahs Huld und Barmherzigkeit) – und gewöhn dir ab, Gaben ‚Glück' oder ‚Zufall' zuzuschreiben.",
 "Werde in EINEM Bereich ein sābiq: zuerst in der Moschee, zuerst beim Helfen, zuerst bei der Spende. Die Sure zeigt: Das Vorauseilen ist der Weg zur Nähe."
]
},

// ───────────────────────── Lektion 47: Asch-Schuʿarāʾ ─────────────────────────
{
sure: 26, offb: 47, name: "Asch-Schuʿarāʾ", arab: "سُورَةُ الشُّعَرَاءِ", de: "Die Dichter", verse: 227, ort: "Mekka",
zeit: "Mittelmekkanisch – mit dem Befehl, die nächsten Verwandten öffentlich zu warnen (26:214)",
kurz: "Sieben Propheten, ein Refrain: Nach jeder Geschichte heißt es „Darin ist wahrlich ein Zeichen, doch die meisten von ihnen sind nicht gläubig. Und dein Herr ist wahrlich der Mächtige, der Barmherzige.“ Mūsā, Ibrāhīm, Nūḥ, Hūd, Ṣāliḥ, Lūṭ, Schuʿaib – jeder sagt seinem Volk denselben Satz: „Ich bin euch ein vertrauenswürdiger Gesandter. So fürchtet Allah und gehorcht mir. Ich verlange von euch keinen Lohn dafür.“ Mittendrin das wunderschöne Gebet Ibrāhīms um ein „gesundes Herz“ (qalb salīm) – das einzige, was am Tag der Auferstehung nützt. Am Ende die Antwort auf den Vorwurf, der Prophet ﷺ sei ein Dichter: Dichter wandern in jedem Tal umher und sagen, was sie nicht tun – außer denen, die glauben und Gutes tun.",
schluessel: {arab: "يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ ۝ إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ", ueb: "… am Tag, an dem weder Besitz noch Söhne nützen, außer wer zu Allah mit einem gesunden Herzen kommt.", ref: "26:88–89"},
kontext: ["Mit 227 Versen ist Asch-Schuʿarāʾ nach Al-Baqara die Sure mit den meisten Versen – aber die Verse sind kurz, rhythmisch, fast liedhaft. Gerade deshalb ist die Pointe am Ende so stark: Eine Sure, die klingt wie große Poesie, erklärt, warum der Koran KEINE Poesie ist. Dichter (in der arabischen Kultur Sprachrohre von Stämmen, Fehden und Begierden) sagen, was sie nicht tun; der Prophet ﷺ tut, was er sagt.",
"In diese Sure fällt der Befehl 26:214: „Und warne deine nächsten Verwandten.“ Daraufhin stieg der Prophet ﷺ auf den Ṣafā und rief die Clans der Quraisch (vgl. Lektion 6 zu Abū Lahab), und er rief auch einzeln: „O Fāṭima, Tochter Muhammads, rette dich selbst vor dem Feuer – ich vermag dir vor Allah nichts zu nützen“ (Sahih al-Buchari, Nr. 4771; Sahih Muslim, Nr. 204). Daʿwa beginnt in der eigenen Familie – und niemand wird durch Verwandtschaft gerettet.",
"Die sieben Prophetengeschichten sind wie eine Reihe von Spiegeln für den Propheten ﷺ: Jeder Gesandte wurde von der Mehrheit abgelehnt – und jedes Mal endet es mit „dein Herr ist der Mächtige, der Barmherzige“. Mächtig, um die Leugner zu strafen; barmherzig, um die Gläubigen zu retten und den Leugnern lange Zeit zu geben. Gleich zu Beginn tröstet Allah: „Vielleicht grämst du dich zu Tode, weil sie nicht glauben“ (26:3)."],
asbab: [
 {text: "26:214 („Und warne deine nächsten Verwandten“): Der Prophet ﷺ rief daraufhin die Quraisch-Clans und seine eigene Familie bis zu seiner Tochter Fāṭima und mahnte sie, sich selbst vor dem Feuer zu retten.", quelle: "Sahih al-Buchari, Nr. 4771; Sahih Muslim, Nr. 204"},
 {text: "26:224–227 (die Dichter): Nach den Tafsir-Werken richteten sich die Verse gegen die Schmähdichter der Quraisch; als die muslimischen Dichter (Ḥassān ibn Thābit, ʿAbdullāh ibn Rawāḥa, Kaʿb ibn Mālik) besorgt waren, wurde die Ausnahme (26:227) als ihr Trost verstanden.", quelle: "Tafsir aṭ-Ṭabarī / Ibn Kathīr zu 26:224 ff. (Tafsir-Bericht, Kette nicht durchgehend sahih)"}
],
begriffe: [
 {arab: "بَاخِعٌ نَّفْسَك", tr: "bāchiʿun nafsak", wurzel: "b-ch-ʿ", erkl: "„Dass du dich (vor Kummer) zugrunde richtest“ (26:3) – der Prophet ﷺ litt so sehr unter dem Unglauben seines Volkes, dass Allah ihn tröstet. Daʿwa aus Liebe kann wehtun – aber die Herzen gehören Allah."},
 {arab: "رَسُولٌ أَمِين", tr: "rasūlun amīn", wurzel: "ʾ-m-n", erkl: "„Ein vertrauenswürdiger Gesandter“ – fünfmal fast wortgleich (Nūḥ, Hūd, Ṣāliḥ, Lūṭ, Schuʿaib). Alle Propheten stellen zuerst ihre Vertrauenswürdigkeit fest – wie Muhammad ﷺ, „al-Amīn“, vor seiner Mission."},
 {arab: "قَلْبٌ سَلِيم", tr: "qalbun salīm", wurzel: "s-l-m", erkl: "„Ein gesundes/heiles Herz“ (26:89) – frei von Schirk, Zweifel, Groll, Hochmut und Liebe zur Sünde. Das Zielbild der Tazkiya in zwei Wörtern: Am Ende zählt nicht, was du hast, sondern welches Herz du bringst."},
 {arab: "أَتَبْنُونَ بِكُلِّ رِيعٍ آيَةً تَعْبَثُونَ", tr: "āyatan taʿbathūn", wurzel: "ʿ-b-th", erkl: "26:128: Hūd fragt ʿĀd: „Baut ihr auf jeder Anhöhe ein Wahrzeichen, um zu spielen (taʿbathūn)?“ – Prestigebauten ohne Nutzen. Eine koranische Kritik an Protz-Architektur und Statussymbolen."},
 {arab: "الْكَيْل وَالْمِيزَان", tr: "al-kail wa-l-mīzān", wurzel: "k-y-l / w-z-n", erkl: "Maß und Gewicht – Schuʿaibs Thema (26:181–183): „Gebt volles Maß … wiegt mit der richtigen Waage … schmälert den Menschen nicht ihre Sachen.“ Wirtschaftsehrlichkeit ist Prophetenbotschaft."},
 {arab: "الشُّعَرَاء", tr: "asch-schuʿarāʾ", wurzel: "sch-ʿ-r", erkl: "Die Dichter – von schaʿara: fühlen, wahrnehmen. 26:225–226: „Siehst du nicht, dass sie in jedem Tal umherirren und dass sie sagen, was sie nicht tun?“ Kritik an Worten ohne Wahrheit und ohne Tat – nicht an Sprache und Kunst an sich (26:227)."}
],
tafsir: [
 {vers: "Verse 1–68: Mūsā", text: "Nach dem Trost an den Propheten ﷺ (26:3–4: Allah könnte ein zwingendes Zeichen senden, will aber freien Glauben) die ausführliche Mūsā-Geschichte, hier mit Schwerpunkt auf dem Gespräch mit Pharao. Pharao erinnert ihn an seine Kindheit im Palast und an den Totschlag: „Haben wir dich nicht bei uns großgezogen?“ Mūsās ehrliche Antwort: „Ich tat es damals, als ich zu den Irrenden gehörte“ – er beschönigt nichts. Dann die Gottesfrage („Was ist der Herr der Welten?“), das Zauberer-Duell, der Glaube der Zauberer, der Auszug. Am Meer sagen die Gefährten: „Wir werden eingeholt!“ – Mūsās Antwort ist pures Tawakkul: „Keineswegs! Mein Herr ist mit mir, Er wird mich leiten“ (26:62). Ibn Kathīr: In der ausweglosesten Lage ein Satz ohne Zweifel – und dann teilt sich das Meer."},
 {vers: "Verse 69–104: Ibrāhīm und das gesunde Herz", text: "Ibrāhīm fragt Vater und Volk: „Was betet ihr an?“ – „Götzen, denen wir ergeben bleiben.“ – „Hören sie euch, wenn ihr ruft? Nützen oder schaden sie euch?“ – „Wir fanden unsere Väter so handelnd.“ Dann sein Bekenntnis, das jeder auswendig lernen sollte: „Der mich erschaffen hat und mich rechtleitet; Der mir zu essen und zu trinken gibt; und wenn ich krank bin, Er heilt mich; Der mich sterben lässt und wieder lebendig macht; und von Dem ich hoffe, dass Er mir meine Verfehlungen am Tag des Gerichts vergibt“ (26:78–82). Beachte den Adab: „wenn ICH krank bin“ – die Krankheit schreibt er sich zu, die Heilung Allah. Dann sein Gebet (83–89): um Weisheit, um Zugehörigkeit zu den Rechtschaffenen, um einen guten Ruf bei den Späteren, um das Paradies – und „lass mich nicht zuschanden werden am Tag, an dem weder Besitz noch Söhne nützen, außer wer mit einem gesunden Herzen kommt“."},
 {vers: "Verse 105–159: Nūḥ, Hūd, Ṣāliḥ", text: "Nūḥs Volk verachtet die Gläubigen: „Sollen wir dir glauben, wo dir die Niedrigsten folgen?“ – Nūḥ: „Ich verstoße die Gläubigen nicht“ (vgl. ʿAbasa, Lektion 24). Hūd zu ʿĀd: Prestigebauten auf jedem Hügel, Paläste, „als ob ihr ewig lebtet“, und Gewalt „wie Tyrannen“. Ṣāliḥ zu Ṯamūd: „Meint ihr, ihr werdet in Sicherheit gelassen in dem, was hier ist – in Gärten und Quellen, Saaten und Palmen?“ und „gehorcht nicht dem Befehl der Maßlosen, die auf der Erde Unheil stiften“ (26:151–152). As-Saʿdī: Jede Zivilisation fällt an ihrer Spezialsünde – Verachtung der Schwachen, Prunk und Gewalt, Sorglosigkeit im Wohlstand. Und jeder Prophet sagt denselben Satz: „Ich verlange von euch keinen Lohn.“"},
 {vers: "Verse 160–191: Lūṭ und Schuʿaib", text: "Lūṭ benennt die Sünde seines Volkes klar: „Geht ihr unter den Weltenbewohnern zu den Männern und lasst eure Gattinnen, die euer Herr für euch erschaffen hat? Nein, ihr seid Leute, die Übertretungen begehen.“ Ihre Antwort: Vertreibung – „sie sind Leute, die sich rein halten wollen“. Schuʿaib (zu den Leuten des Dickichts, al-Aika) spricht über Wirtschaft: volles Maß, richtige Waage, kein Betrug, kein Unheil stiften. Al-Qurṭubī: Der Koran stellt sexuelle und wirtschaftliche Ethik ohne Rangunterschied nebeneinander – beides sind Prophetenthemen, beides sind Fragen des Gottesgehorsams."},
 {vers: "Verse 192–227: Offenbarung, Verwandte und Dichter", text: "„Und er (der Koran) ist eine Herabsendung vom Herrn der Welten; mit ihm ist der vertrauenswürdige Geist (Dschibrīl) herabgekommen auf dein Herz … in deutlicher arabischer Sprache. Und er ist in den Schriften der Früheren (angekündigt).“ Dann die Anweisungen für die Daʿwa: „Warne deine nächsten Verwandten“ (214), „senke deinen Flügel für die Gläubigen, die dir folgen“ (215 – Demut und Zärtlichkeit gegenüber den eigenen Leuten), „verlass dich auf den Mächtigen, den Barmherzigen, Der dich sieht, wenn du (zum Gebet) stehst, und deine Bewegungen unter den sich Niederwerfenden“ (217–219). Dann die Dichter-Verse: Die Satane kommen herab „auf jeden lügnerischen Sünder“, nicht auf den Wahrhaftigen; die Dichter irren in jedem Tal umher – „außer denen, die glauben, rechtschaffene Werke tun, Allahs viel gedenken und sich wehren, nachdem ihnen Unrecht geschehen ist“ (227). Ibn Kathīr: Die Ausnahme rettet die gute Dichtung – der Prophet ﷺ selbst ermutigte Ḥassān ibn Thābit."}
],
ahadith: [
 {text: "Nach der Herabsendung von 26:214: „O Leute von Quraisch, kauft euch selbst (von Allah) frei, ich vermag euch vor Allah nichts zu nützen … O Fāṭima, Tochter Muhammads, bitte mich von meinem Vermögen, was du willst – vor Allah vermag ich dir nichts zu nützen.“", quelle: "Sahih al-Buchari, Nr. 4771; Sahih Muslim, Nr. 204"},
 {text: "Zu Ḥassān ibn Thābit: „Schmähe sie (in Versen) – und Dschibrīl ist mit dir.“", quelle: "Sahih al-Buchari, Nr. 4124; Sahih Muslim, Nr. 2486"},
 {text: "„Ein Teil der Dichtung ist wahrlich Weisheit.“", quelle: "Sahih al-Buchari, Nr. 6145"},
 {text: "„Wahrlich, im Körper gibt es ein Stück Fleisch – ist es gesund, ist der ganze Körper gesund; ist es verdorben, ist der ganze Körper verdorben: Das ist das Herz.“ – zum qalb salīm.", quelle: "Sahih al-Buchari, Nr. 52; Sahih Muslim, Nr. 1599"}
],
hanafi: "Zu den Dichter-Versen (26:224–227) entspricht die hanafitische Position der allgemeinen der Gelehrten: Dichtung ist nach ihrem Inhalt zu beurteilen – erlaubt und sogar lobenswert, wenn sie Wahrheit, Weisheit, Lob Allahs und Seines Gesandten ﷺ oder Verteidigung gegen Unrecht enthält; verboten, wenn sie Lüge, Verleumdung, Schamloses oder das Verherrlichen von Sünde transportiert. Der Maßstab ist 26:227. Dasselbe gilt sinngemäß für Lieder, Reden und Inhalte in sozialen Medien.",
umsetzung: [
 "Lerne Ibrāhīms Bekenntnis (26:78–82) auswendig und sprich es bei Krankheit: „Wenn ich krank bin, Er heilt mich.“ Beachte den Adab – das Gute Allah zuschreiben, das Mangelhafte dir.",
 "Mach qalb salīm zu deinem Tazkiya-Ziel: Liste die fünf ‚Krankheiten' (Schirk-Neigungen, Zweifel, Groll, Hochmut, Sündenliebe) und prüfe, welche dein Herz am meisten belastet.",
 "Setze 26:214 um: Hast du deiner eigenen Familie je mit Liebe vom Dīn erzählt? Fang beim Nächsten an – freundlich, ohne Druck, aber klar.",
 "Wende den Dichter-Test (26:226) auf dich an: Sage ich, was ich nicht tue? Reduziere das Gefälle zwischen Reden und Handeln – und prüfe deine Medien danach, ob sie Wahrheit oder nur Gefühl transportieren.",
 "Lerne Mūsās Satz am Meer: kallā, inna maʿiya rabbī sa-yahdīn (26:62) – für jede Lage, in der es keinen Ausweg mehr zu geben scheint."
]
},

// ───────────────────────── Lektion 48: An-Naml ─────────────────────────
{
sure: 27, offb: 48, name: "An-Naml", arab: "سُورَةُ النَّمْلِ", de: "Die Ameisen", verse: 93, ort: "Mekka",
zeit: "Mittelmekkanisch – unmittelbar nach Asch-Schuʿarāʾ, mit ähnlichem Aufbau, aber neuem Schwerpunkt: Dankbarkeit in der Macht",
kurz: "Die Sure von Sulaimān, dem König, der die Sprache der Vögel verstand und dem Dschinn, Menschen und Vögel dienten – und der trotzdem beim Lächeln über eine Ameise betete: „Mein Herr, gib mir ein, für Deine Gunst dankbar zu sein.“ Die Ameise warnt ihr Volk vor seinen Truppen; der Wiedehopf bringt die Nachricht von der Königin von Sabaʾ, deren Volk die Sonne anbetet (Sadschda-Vers 27:26); ein Brief Sulaimāns beginnt mit „Bismillāhi r-Raḥmāni r-Raḥīm“; der Thron der Königin wird „in einem Augenblick“ herbeigebracht; und die Königin unterwirft sich am Ende „mit Sulaimān Allah, dem Herrn der Welten“. Dazu die Kette von Fragen „Gibt es einen Gott neben Allah?“ – mit dem berühmten Vers: „Wer erhört den Bedrängten, wenn er Ihn anruft, und nimmt das Übel hinweg?“",
schluessel: {arab: "أَمَّن يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ", ueb: "Oder (ist besser) Der, Der den Bedrängten erhört, wenn er Ihn anruft, und das Böse hinwegnimmt …?", ref: "27:62"},
kontext: ["An-Naml folgt in der Offenbarung direkt auf Asch-Schuʿarāʾ und wiederholt kurz Mūsā (Feuer, Stab, Hand), Ṣāliḥ und Lūṭ. Neu ist die große Sulaimān-Erzählung – und sie hat eine klare Funktion: Den Quraisch, die fürchteten, mit dem Islam ihre Macht zu verlieren, zeigt sie einen Propheten mit mehr Macht als jeder König der Erde, der seine Macht ganz Allah unterstellt. Macht und Glaube sind kein Widerspruch – Macht ohne Dankbarkeit ist das Problem.",
"Die Königin von Sabaʾ (in späterer Überlieferung Bilqīs genannt, der Name steht nicht im Koran) ist eine der eindrucksvollsten Frauengestalten des Korans: Sie berät sich mit ihrem Rat, statt allein zu entscheiden; sie lehnt den Krieg ab („Könige verderben eine Stadt, wenn sie sie betreten“); sie prüft Sulaimān mit einem Geschenk; sie denkt nach, als sie ihren Thron wiedererkennt; und sie bekennt ihren Irrtum ohne Ausrede: „Mein Herr, ich habe mir selbst Unrecht getan.“ Ihr Islam ist Einsicht, nicht Unterwerfung unter einen Eroberer – „mit Sulaimān“, nicht ‚unter' ihm.",
"Der zweite Teil (27:59–93) ist eine Beweisführung in Fragen: Wer hat Himmel und Erde erschaffen, Regen herabgesandt, die Erde fest gemacht, den Bedrängten erhört, euch in der Finsternis von Land und Meer geleitet? Fünfmal: „Gibt es einen Gott neben Allah?“ – und jedes Mal ist die ehrliche Antwort: Nein."],
asbab: ["Für An-Naml ist kein einzelner Offenbarungsanlass sahih überliefert; sie gehört zu den mittelmekkanischen Erzählsuren."],
begriffe: [
 {arab: "مَنطِقَ الطَّيْر", tr: "manṭiq aṭ-ṭair", wurzel: "n-ṭ-q", erkl: "„Die Sprache der Vögel“ (27:16) – Sulaimāns besondere Gabe. Sein Kommentar: „Das ist wahrlich die offenkundige Huld (Allahs).“ Jede Fähigkeit wird sofort als Gabe benannt."},
 {arab: "النَّمْل", tr: "an-naml", wurzel: "n-m-l", erkl: "Die Ameisen. 27:18: Eine Ameise warnt: „Geht in eure Wohnungen, damit Sulaimān und seine Heerscharen euch nicht zertreten, ohne es zu merken.“ Bemerkenswert: Sie entschuldigt Sulaimān im Voraus („ohne es zu merken“) – sie unterstellt ihm keine Bosheit. Adab sogar bei der Ameise."},
 {arab: "أَوْزِعْنِي", tr: "auziʿnī", wurzel: "w-z-ʿ", erkl: "„Gib mir ein / sporne mich an“ (27:19): „Mein Herr, gib mir ein, für Deine Gunst dankbar zu sein, die Du mir und meinen Eltern erwiesen hast, und Gutes zu tun, das Dir gefällt.“ Sulaimāns Reaktion auf Macht: Er bittet um Dankbarkeit – nicht um mehr Macht."},
 {arab: "الْهُدْهُد", tr: "al-hudhud", wurzel: "–", erkl: "Der Wiedehopf – ein kleiner Vogel, der dem König sagt: „Ich habe erfasst, was du nicht erfasst hast“ (27:22). Wissen ist nicht an Rang gebunden; ein großer König hört dem Kleinsten zu – und prüft trotzdem: „Wir werden sehen, ob du die Wahrheit sagst.“"},
 {arab: "عِندَهُ عِلْمٌ مِّنَ الْكِتَاب", tr: "ʿindahū ʿilmun mina l-kitāb", wurzel: "ʿ-l-m", erkl: "„Der Wissen aus der Schrift hatte“ (27:40) – er bringt den Thron schneller als ein Ifrīt, „bevor dein Blick zu dir zurückkehrt“. Wissen aus der Offenbarung ist stärker als jede Kraft der Dschinn."},
 {arab: "الْمُضْطَرّ", tr: "al-muḍṭarr", wurzel: "ḍ-r-r", erkl: "„Der Bedrängte/Notleidende“ (27:62) – wer keinen Ausweg mehr hat außer Allah. Die Gelehrten: Das Duʿā des Bedrängten hat besondere Kraft, weil es ganz aufrichtig ist – selbst die Götzendiener riefen auf hoher See nur noch Allah an."}
],
tafsir: [
 {vers: "Verse 1–14: Rechtleitung und Mūsā", text: "Der Koran ist „Rechtleitung und frohe Botschaft für die Gläubigen, die das Gebet verrichten und die Zakat entrichten und vom Jenseits fest überzeugt sind“. Dann kurz Mūsā am Feuer: „Gesegnet ist, wer im Feuer und wer in seiner Umgebung ist“ und die Zeichen. 27:14 benennt die Psychologie der Leugner präzise: „Sie leugneten sie aus Ungerechtigkeit und Überheblichkeit, obwohl ihre Seelen von ihnen überzeugt waren.“ Ibn Kathīr: Das Problem war nie Mangel an Beweisen, sondern innerer Widerstand gegen das, was man eigentlich schon weiß."},
 {vers: "Verse 15–19: Sulaimān und die Ameise", text: "Dāwūd und Sulaimān erhielten Wissen, „und sie sagten: Lob sei Allah, Der uns vor vielen Seiner gläubigen Diener bevorzugt hat“. Sulaimān erbt Prophetie und Königtum, kennt die Vogelsprache, sein Heer aus Dschinn, Menschen und Vögeln marschiert in Ordnung. Im Tal der Ameisen hört er die Warnung der Ameise – „und er lächelte, lachend über ihre Worte“ – und betet sofort um Dankbarkeit. As-Saʿdī: Der mächtigste König der Geschichte hört einer Ameise zu, freut sich über sie, und sein erster Gedanke ist nicht Stolz, sondern Schukr. Daraus leiten die Gelehrten die Achtung vor Tieren ab (vgl. den Hadith über das Verbot, Ameisen zu töten)."},
 {vers: "Verse 20–44: der Wiedehopf und die Königin von Sabaʾ", text: "Sulaimān vermisst den Wiedehopf und kündigt Strafe an – es sei denn, er bringt einen klaren Grund. Der Wiedehopf berichtet von einer Königin mit gewaltigem Thron, deren Volk die Sonne anbetet, „und der Satan hat ihnen ihre Taten ausgeschmückt“ – „damit sie sich nicht vor Allah niederwerfen, Der das Verborgene hervorbringt … Allah, es gibt keinen Gott außer Ihm, dem Herrn des gewaltigen Throns“ (27:25–26, Sadschda-Stelle). Sulaimān schickt einen Brief: „Er ist von Sulaimān, und er lautet: Im Namen Allahs, des Allerbarmers, des Barmherzigen – seid nicht überheblich gegen mich und kommt zu mir als Gottergebene.“ Die Königin berät sich, rät vom Krieg ab, schickt ein Geschenk. Sulaimān lehnt ab: „Wollt ihr mich mit Besitz unterstützen? Was Allah mir gegeben hat, ist besser.“ Der Thron wird herbeigeschafft – und Sulaimān sagt: „Dies ist von der Huld meines Herrn, um mich zu prüfen, ob ich dankbar oder undankbar bin“ (27:40). Die Königin erkennt den veränderten Thron, betritt den Palast mit dem gläsernen Boden, hält ihn für Wasser – und begreift: Sie hat das Sichtbare für das Wirkliche gehalten, wie ihr Volk die Sonne für einen Gott. „Mein Herr, ich habe mir selbst Unrecht getan, und ich ergebe mich mit Sulaimān Allah, dem Herrn der Welten.“"},
 {vers: "Verse 45–58: Ṣāliḥ und Lūṭ", text: "Kurz die Verschwörung der neun Unheilstifter gegen Ṣāliḥ („Lasst uns schwören, ihn und seine Familie nachts zu überfallen“) – „sie schmiedeten eine List, und Wir schmiedeten eine List, ohne dass sie es merkten“ (vgl. Lektion 36). Dann Lūṭ und sein Volk, das die Familie Lūṭs vertreiben will, „weil sie Leute sind, die sich rein halten“. Die Ironie: Reinheit wird zum Ausweisungsgrund."},
 {vers: "Verse 59–93: Gibt es einen Gott neben Allah?", text: "Fünf Fragen, fünf Beweisbereiche: Schöpfung und Regen („ihr hättet ihre Bäume nicht wachsen lassen können“), die feste Erde mit Flüssen und Bergen und der Schranke zwischen den Meeren, der Bedrängte, der erhört wird (27:62), Wegweisung in Dunkelheit von Land und Meer und die Winde als Vorboten des Regens, Erschaffung und Wiederholung und Versorgung. Nach jeder Frage: „Gibt es einen Gott neben Allah?“ Al-Qurṭubī zu 27:62: Allah nennt die Erhörung des Bedrängten als Beweis Seiner Göttlichkeit – wer in der Not betet, erlebt Tauhīd am eigenen Leib. 27:65: „Niemand in den Himmeln und auf der Erde kennt das Verborgene außer Allah“ (vgl. Lektion 40). Am Ende der Posaunenstoß und die Berge, die „wie Wolken vorüberziehen“, obwohl man sie für fest hält – und der Auftrag des Propheten ﷺ: „Mir wurde nur befohlen, dem Herrn dieser Stadt zu dienen … und den Koran vorzutragen.“"}
],
ahadith: [
 {text: "Der Prophet ﷺ verbot, vier Tiere zu töten: die Ameise, die Biene, den Wiedehopf und den Würger (ṣurad).", quelle: "Sunan Abū Dāwūd, Nr. 5267; sahih"},
 {text: "Ein Prophet wurde von einer Ameise gestochen und ließ das ganze Ameisenvolk verbrennen. Da offenbarte ihm Allah: „Weil dich eine Ameise gestochen hat, hast du ein Volk verbrannt, das (Allah) preist?“", quelle: "Sahih al-Buchari, Nr. 3019; Sahih Muslim, Nr. 2241"},
 {text: "Das Gebet in Not (duʿāʾ al-karb): „Lā ilāha illa llāhu l-ʿaẓīmu l-ḥalīm, lā ilāha illa llāhu rabbu l-ʿarschi l-ʿaẓīm, lā ilāha illa llāhu rabbu s-samāwāti wa-rabbu l-arḍi wa-rabbu l-ʿarschi l-karīm.“ – passend zu 27:62.", quelle: "Sahih al-Buchari, Nr. 6346; Sahih Muslim, Nr. 2730"},
 {text: "„Drei Gebete werden erhört, daran besteht kein Zweifel: das Gebet des Unterdrückten, das Gebet des Reisenden und das Gebet des Vaters für sein Kind.“", quelle: "Sunan Abū Dāwūd, Nr. 1536; hasan"}
],
hanafi: "27:26 ist eine der 14 Sadschda-Stellen: Nach hanafitischer Schule ist die Rezitations-Niederwerfung hier wādschib, beim Lesen und beim Hören. (Ob sie am Ende von Vers 25 oder 26 liegt, wird unterschiedlich gezählt; wer nach Vers 26 niederfällt, hat sie sicher erfüllt.) Inhaltlich passt sie perfekt: Der Wiedehopf klagt, dass ein Volk sich nicht vor Allah niederwirft – der Leser antwortet mit der eigenen Niederwerfung. Zusatz zu 27:30: Die hanafitische Schule zählt die Basmala in 27:30 als Teil des Korantextes (unbestritten), die am Anfang der Suren dagegen als eigenen Vers zur Trennung (vgl. Lektion 5).",
umsetzung: [
 "Lerne Sulaimāns Gebet 27:19 (rabbi auziʿnī an aschkura niʿmatak …) und sprich es immer dann, wenn dir etwas gelingt – Erfolg ist die Zeit für Dank, nicht für Stolz.",
 "Hör auch den ‚Kleinen' zu wie Sulaimān dem Wiedehopf – Kindern, Praktikanten, Neuen in der Gemeinde. Aber prüfe Nachrichten (27:27), bevor du sie weitergibst.",
 "Beginne wichtige Schreiben mit Bismillāh – wie der Brief Sulaimāns (27:30) und wie die Briefe des Propheten ﷺ an die Könige.",
 "Lerne das Duʿāʾ al-karb (Buchari 6346) für Notlagen – und erinnere dich an 27:62: Gerade die Not ist der Moment, in dem das Gebet am nächsten ist.",
 "Mach bei 27:26 die Tilāwa-Sadschda (hanafitisch wādschib) – deine Liste wächst: 7:206, 19:58, 27:26, 38:24, 53:62, 96:19."
]
},

// ───────────────────────── Lektion 49: Al-Qaṣaṣ ─────────────────────────
{
sure: 28, offb: 49, name: "Al-Qaṣaṣ", arab: "سُورَةُ الْقَصَصِ", de: "Die Geschichten", verse: 88, ort: "Mekka",
zeit: "Spätmekkanisch – nach verbreiteter Ansicht wurde Vers 85 auf dem Weg der Hidschra bei al-Dschuḥfa offenbart",
kurz: "Die vollständigste Biografie Mūsās im Koran – von der Wiege bis zur Berufung – erzählt als Geschichte der Schwachen, die Allah stärkt: „Wir wollten denen, die auf der Erde unterdrückt wurden, Gnade erweisen und sie zu Vorbildern und Erben machen.“ Eine Mutter legt ihr Baby in ein Kästchen auf den Fluss – und Allah bringt es ausgerechnet in den Palast des Tyrannen, der alle Jungen töten lässt, und dann zurück an ihre Brust. Ein junger Mann tötet versehentlich, flieht, gibt am Brunnen von Madyan zwei Frauen Wasser und betet: „Mein Herr, ich bin bedürftig nach dem Guten, das Du mir herabsendest.“ Dann der zweite Teil: Qārūn, der reiche Mann, der sagt „Ich habe es nur aufgrund meines Wissens erhalten“ – und mit seinem Haus in der Erde versinkt. Und die Zusage an den Propheten ﷺ, der Mekka verlassen muss: „Der dir den Koran verpflichtend gemacht hat, wird dich zum Ort der Rückkehr zurückbringen.“",
schluessel: {arab: "وَنُرِيدُ أَن نَّمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا فِي الْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ الْوَارِثِينَ", ueb: "Und Wir wollten denen, die auf der Erde unterdrückt wurden, Gnade erweisen und sie zu Vorbildern machen und zu Erben machen.", ref: "28:5"},
kontext: ["Al-Qaṣaṣ fällt in die letzte, härteste Phase Mekkas: Die Muslime waren schwach, verfolgt, kurz vor der Auswanderung. Die Mūsā-Geschichte wird darum aus der Perspektive der Schwachen erzählt: Pharao „hatte die Bewohner in Parteien gespalten, eine Gruppe von ihnen unterdrückte er“ (28:4) – und genau diese unterdrückte Gruppe macht Allah zu Erben. Für die Gefährten in Mekka war das eine Zukunftsansage; zehn Jahre später zogen sie als Sieger in dieselbe Stadt ein.",
"In diese Sure gehört auch der traurigste Moment der mekkanischen Zeit: der Tod Abū Ṭālibs. Der Prophet ﷺ saß bei seinem sterbenden Onkel, der ihn sein Leben lang beschützt hatte, und bat: „Sag lā ilāha illa llāh – ein Wort, mit dem ich bei Allah für dich eintreten kann.“ Abū Dschahl und ʿAbdullāh ibn Abī Umayya hielten dagegen: „Willst du dich von der Religion ʿAbd al-Muṭṭalibs abwenden?“ – und Abū Ṭālib starb auf ihr. Daraufhin wurde offenbart: „Du kannst nicht rechtleiten, wen du liebst, sondern Allah leitet recht, wen Er will“ (28:56; Sahih al-Buchari, Nr. 4772; Sahih Muslim, Nr. 24).",
"Vers 85 schließlich wird nach Ibn ʿAbbās auf Mekka bezogen: „Der dir den Koran verpflichtend gemacht hat, wird dich gewiss zu einem Ort der Rückkehr (maʿād) zurückbringen“ – „nach Mekka“ (Sahih al-Buchari, Nr. 4773). Nach verbreiteter Tafsir-Überlieferung kam er auf dem Weg der Hidschra herab, als der Prophet ﷺ mit Sehnsucht auf seine Stadt zurückblickte. Er kehrte acht Jahre später zurück."],
asbab: [
 {text: "28:56: Tod Abū Ṭālibs, der sich weigerte, das Bekenntnis zu sprechen – „Du kannst nicht rechtleiten, wen du liebst.“", quelle: "Sahih al-Buchari, Nr. 4772 (vgl. 1360); Sahih Muslim, Nr. 24"},
 {text: "28:85: Ibn ʿAbbās: „zu einem Ort der Rückkehr“ – nach Mekka. Nach verbreiteter Tafsir-Überlieferung offenbart bei al-Dschuḥfa auf dem Weg der Hidschra.", quelle: "Sahih al-Buchari, Nr. 4773 (Deutung als Mekka); der Ort der Herabsendung nach Tafsir-Berichten (Ibn Kathīr z. St.)"}
],
begriffe: [
 {arab: "اسْتُضْعِفُوا", tr: "istuḍʿifū", wurzel: "ḍ-ʿ-f", erkl: "„Die schwach gemacht/unterdrückt wurden“ (28:5) – nicht von Natur schwach, sondern durch Unterdrückung geschwächt. Der Koran stellt sich hier ausdrücklich auf die Seite der Mustaḍʿafūn."},
 {arab: "فَارِغًا", tr: "fārighā", wurzel: "f-r-ġ", erkl: "„Leer“ (28:10): „Das Herz der Mutter Mūsās wurde leer“ – leer vor Angst, nur noch Gedanken an ihr Kind. Allah „festigte ihr Herz“. Der Koran beschreibt Mutterangst mit größter Zärtlichkeit."},
 {arab: "فَقِير", tr: "faqīr", wurzel: "f-q-r", erkl: "28:24: „Mein Herr, ich bin bedürftig (faqīr) nach dem Guten, das Du mir herabsendest.“ Mūsā, auf der Flucht, ohne Geld, nach einer guten Tat im Schatten – eines der schönsten Duʿās des Korans (vgl. 35:15 in Lektion 43)."},
 {arab: "الْقَوِيُّ الْأَمِين", tr: "al-qawiyy al-amīn", wurzel: "q-w-y / ʾ-m-n", erkl: "„Der Starke, der Vertrauenswürdige“ (28:26) – die Tochter Schuʿaibs empfiehlt Mūsā als Arbeitskraft: Kompetenz und Vertrauenswürdigkeit. Die Gelehrten nennen das die zwei Grundbedingungen für jedes Amt."},
 {arab: "قَارُون", tr: "Qārūn", wurzel: "–", erkl: "Qārūn – ein reicher Mann aus dem Volk Mūsās, dessen Schlüssel kaum eine Gruppe starker Männer tragen konnte. Sein Satz „Ich habe es nur aufgrund meines Wissens erhalten“ (28:78) ist die Formel jeder Selbstüberschätzung: Erfolg als eigene Leistung statt als Gabe."},
 {arab: "نَصِيبَكَ مِنَ الدُّنْيَا", tr: "naṣībaka mina d-dunyā", wurzel: "n-ṣ-b", erkl: "„Deinen Anteil am Diesseits“ (28:77): „Erstrebe mit dem, was Allah dir gegeben hat, die jenseitige Wohnstätte, und vergiss nicht deinen Anteil am Diesseits.“ Islam ist keine Weltflucht – aber der Anteil am Diesseits ist der Teil, nicht das Ganze."}
],
tafsir: [
 {vers: "Verse 1–13: das Kästchen auf dem Fluss", text: "Pharao spaltet sein Volk, tötet die Söhne der Unterdrückten – und Allah plant das Gegenteil (28:5–6). Die Mutter Mūsās erhält die Eingebung: „Stille ihn; und wenn du um ihn fürchtest, so wirf ihn ins Wasser und fürchte dich nicht und sei nicht traurig – Wir bringen ihn dir zurück.“ Pharaos Leute nehmen das Kästchen auf, „damit er ihnen ein Feind und Kummer werde“ (die Ironie: Sie ziehen ihren eigenen Untergang groß). Die Frau Pharaos bittet: „Ein Augentrost für mich und dich – tötet ihn nicht!“ Das Baby verweigert alle Ammen, die Schwester bietet unauffällig ihre Familie an – und Mūsā liegt wieder an der Brust seiner Mutter, „damit ihr Auge sich freue … und damit sie wisse, dass Allahs Versprechen wahr ist“. Ibn Kathīr: Allah erfüllt Sein Versprechen sogar über den Palast des Feindes."},
 {vers: "Verse 14–28: Totschlag, Flucht, Brunnen", text: "Der erwachsene Mūsā greift in einen Streit ein und tötet mit einem Faustschlag ungewollt einen Ägypter. Sofort: „Das ist vom Werk des Satans … Mein Herr, ich habe mir selbst Unrecht getan, so vergib mir“ – und Allah vergibt (28:16). Sein Gelöbnis: „Ich werde niemals den Übeltätern Beistand leisten.“ Er flieht nach Madyan, ohne Ziel, und betet: „Vielleicht leitet mich mein Herr den rechten Weg.“ Am Brunnen sieht er zwei Frauen, die zurückstehen, weil die Hirten drängeln; er tränkt ihre Tiere, zieht sich in den Schatten zurück und betet 28:24. Eine der beiden kommt zurück, „schamhaft gehend“ (taschī ʿalā stiḥyāʾ), und lädt ihn zu ihrem Vater ein. Er findet Arbeit, Unterkunft, Ehe und Sicherheit. As-Saʿdī: Ein Mann ohne alles tut ohne Gegenleistung Gutes – und Allah antwortet auf das Duʿā des Bedürftigen mit allem, was er braucht."},
 {vers: "Verse 29–50: Feuer, Mission, Ablehnung", text: "Nach Ablauf der Dienstzeit zieht Mūsā mit seiner Familie los, sieht das Feuer am Berg, hört den Ruf: „O Mūsā, Ich bin Allah, der Herr der Welten.“ Die Zeichen, die Angst („Ich habe von ihnen einen Menschen getötet und fürchte, sie töten mich“), die Bitte um Hārūn, „der beredter ist als ich“. Pharao verspottet Mūsā und lässt Hāmān einen Turm bauen, „damit ich zum Gott Mūsās hinaufsteige“ – Hochmut als Bauprojekt. Pharao und sein Heer werden ins Meer geworfen: „Wir machten sie zu Anführern, die zum Feuer rufen.“ Dann an die Quraisch: Sie hätten gesagt, warum er nicht dasselbe wie Mūsā bekam – aber Mūsās Buch hätten sie auch geleugnet. 28:50: „Wer ist weiter abgeirrt als der, der seiner Neigung ohne Rechtleitung von Allah folgt?“"},
 {vers: "Verse 51–75: Rechtleitung gehört Allah", text: "Lob für Schriftbesitzer, die den Koran als Wahrheit erkennen: „Sie erhalten ihren Lohn zweifach, weil sie standhaft waren, das Böse mit dem Guten abwehren“ und auf leeres Gerede mit „Friede sei mit euch, wir suchen nicht die Unwissenden“ antworten (28:52–55). Dann 28:56 mit dem Anlass Abū Ṭālib – einer der schmerzhaftesten und zugleich befreiendsten Verse: Du bist nicht verantwortlich für die Rechtleitung der Menschen, die du liebst; du bist verantwortlich für die Einladung. Die Quraisch fürchten: „Wenn wir der Rechtleitung folgen, werden wir aus unserem Land weggerissen“ – Antwort: „Haben Wir ihnen nicht ein sicheres Heiligtum gegeben?“ (vgl. Lektion 29). 28:71–72: Was, wenn Allah euch ewige Nacht oder ewigen Tag gäbe – welcher Gott brächte euch das Gegenteil?"},
 {vers: "Verse 76–88: Qārūn und die Rückkehr", text: "Qārūn „überhob sich gegen sie“ mit Schätzen, deren Schlüssel schwer zu tragen waren. Sein Volk rät ihm (28:76–77): Sei nicht übermütig; erstrebe die jenseitige Wohnstätte; vergiss nicht deinen Anteil am Diesseits; tu Gutes, wie Allah dir Gutes getan hat; strebe nicht nach Unheil. Seine Antwort: „Ich habe es nur aufgrund meines Wissens erhalten.“ Er zieht in seinem Prunk aus; die Dunya-Liebhaber sagen: „O hätten wir doch, was Qārūn gegeben wurde!“; die Wissenden: „Wehe euch! Der Lohn Allahs ist besser.“ Dann lässt Allah die Erde ihn und sein Haus verschlingen – und dieselben Neider sagen am nächsten Morgen: „Wäre Allah uns nicht gnädig gewesen, Er hätte auch uns versinken lassen.“ 28:83: „Jene jenseitige Wohnstätte bestimmen Wir für diejenigen, die auf der Erde weder Überheblichkeit noch Unheil wollen.“ Dann die Zusage 28:85 (Rückkehr nach Mekka) und der Schlussvers: „Alles ist vergänglich außer Seinem Angesicht.“"}
],
ahadith: [
 {text: "Am Sterbebett Abū Ṭālibs: „O Onkel, sag lā ilāha illa llāh – ein Wort, mit dem ich bei Allah für dich eintreten kann.“ – Anlass von 28:56.", quelle: "Sahih al-Buchari, Nr. 4772; Sahih Muslim, Nr. 24"},
 {text: "Ibn ʿAbbās zu 28:85: „lā rādduka ilā maʿād – nach Mekka.“", quelle: "Sahih al-Buchari, Nr. 4773"},
 {text: "„Drei erhalten ihren Lohn zweifach: ein Mann von den Schriftbesitzern, der an seinen Propheten glaubte und dann an Muhammad …“ – zu 28:52–54.", quelle: "Sahih al-Buchari, Nr. 97; Sahih Muslim, Nr. 154"},
 {text: "„Wer in dessen Herzen ein Stäubchen Hochmut ist, betritt nicht das Paradies.“ – zu Qārūn und 28:83.", quelle: "Sahih Muslim, Nr. 91"}
],
hanafi: null,
umsetzung: [
 "Lerne Mūsās Duʿā 28:24 (rabbi innī limā anzalta ilayya min chairin faqīr) für Zeiten von Arbeitslosigkeit, Wohnungssuche, Neuanfang – und tu vorher etwas Gutes ohne Gegenleistung, wie er am Brunnen.",
 "Wende 28:56 auf deine Familie an: Rede, lade ein, bete für sie – und übergib die Rechtleitung Allah. Das nimmt dir eine Last ab, die du nie tragen solltest.",
 "Mach den Qārūn-Test: Sagst du über deinen Erfolg „das habe ich mir erarbeitet“ oder „das hat Allah mir gegeben“? Beides kann stimmen – aber nur die zweite Haltung ist sicher.",
 "Lebe 28:77 ausgewogen: Plane dein Jenseits mit deinem Diesseits (Beruf, Geld, Zeit) – und gönn dir deinen erlaubten Anteil ohne schlechtes Gewissen.",
 "Bei Personalentscheidungen (Arbeit, Ehrenamt, Gemeinde): Prüfe qawī und amīn – Kompetenz UND Vertrauenswürdigkeit."
]
},

// ───────────────────────── Lektion 50: Al-Isrāʾ ─────────────────────────
{
sure: 17, offb: 50, name: "Al-Isrāʾ", arab: "سُورَةُ الْإِسْرَاءِ", de: "Die Nachtreise", verse: 111, ort: "Mekka",
zeit: "Spätmekkanisch – nach der Nachtreise nach Jerusalem und der Himmelfahrt (ca. ein Jahr vor der Hidschra)",
kurz: "Die Sure beginnt mit dem großen Wunder: „Preis sei Dem, Der Seinen Diener bei Nacht von der Heiligen Moschee zur Fernsten Moschee reisen ließ.“ Doch ihr Kern ist kein Bericht über Wunder, sondern ein Grundgesetz für das Leben: die islamischen ‚zehn Gebote' (17:22–39) – Allah allein dienen, die Eltern ehren und ihnen nicht einmal „uff“ sagen, Verwandten, Armen und Reisenden ihr Recht geben, nicht verschwenden, keine Kinder aus Angst vor Armut töten, sich der Unzucht nicht nähern, nicht töten, das Gut der Waise nicht antasten, Versprechen halten, richtig messen, nicht dem folgen, wovon man kein Wissen hat, nicht hochmütig auf der Erde gehen. Dazu die Würde des Menschen („Wir haben die Kinder Ādams geehrt“), die Frage nach dem Geist (rūḥ) und das Zeugnis, dass Menschen und Dschinn zusammen keinen Koran hervorbringen könnten.",
schluessel: {arab: "سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِّنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى", ueb: "Preis sei Dem, Der Seinen Diener bei Nacht von der Heiligen Moschee zur Fernsten Moschee reisen ließ …", ref: "17:1"},
kontext: ["Etwa ein Jahr vor der Hidschra, nach dem ‚Jahr der Trauer' (Tod Chadīdschas und Abū Ṭālibs) und der Demütigung in Ṭāʾif, wurde der Prophet ﷺ in einer Nacht von Mekka nach Jerusalem gebracht (isrāʾ), wo er die Propheten im Gebet leitete, und von dort durch die Himmel geführt (miʿrādsch) – bis zur sidrat al-muntahā (vgl. Lektion 23), wo ihm die fünf täglichen Gebete auferlegt wurden (Sahih al-Buchari, Nr. 349; Sahih Muslim, Nr. 162). Als er am Morgen davon erzählte, lachten die Quraisch; einige Schwache fielen vom Glauben ab. Sie fragten ihn nach Einzelheiten Jerusalems – und Allah zeigte ihm die Stadt, sodass er sie beschrieb (Sahih al-Buchari, Nr. 3886). Abū Bakr sagte, als man ihm davon erzählte: „Wenn er es gesagt hat, dann ist es wahr“ – daher sein Beiname aṣ-Ṣiddīq.",
"Die Sure wird auch Banī Isrāʾīl genannt, weil sie mit der Geschichte der Kinder Israels fortfährt: Zweimal würden sie auf der Erde Unheil stiften, zweimal würde Allah Feinde gegen sie schicken (17:4–8). Die Botschaft an die Umma, die gerade dabei ist, ein Gemeinwesen zu gründen: Auch ihr seid nicht immun – „Wenn ihr Gutes tut, tut ihr es für euch selbst; und wenn ihr Böses tut, ist es gegen euch selbst.“",
"Dass die Lebensregeln (17:22–39) direkt nach der Himmelfahrt stehen, ist bedeutsam: Die Gemeinde stand kurz vor der Hidschra und der Gründung einer Gesellschaft. Die Grundwerte dieser Gesellschaft kamen zuerst – Familie, soziale Gerechtigkeit, Leben, Eigentum, Wahrheit, Demut – erst danach in Medina die detaillierten Gesetze. Der Prophet ﷺ las diese Sure (zusammen mit az-Zumar) jede Nacht vor dem Schlafen (Sunan at-Tirmidhī, Nr. 2920; hasan)."],
asbab: [
 {text: "17:1: die Nachtreise und Himmelfahrt des Propheten ﷺ.", quelle: "Sahih al-Buchari, Nr. 349 und 3887; Sahih Muslim, Nr. 162"},
 {text: "17:85 („Sie fragen dich nach dem Geist …“): Juden fragten den Propheten ﷺ nach dem Geist, als er in Medina an einem Palmstamm lehnte – er schwieg, bis die Offenbarung kam (der Vers wurde nach manchen Gelehrten wiederholt bzw. in Medina erneut herabgesandt).", quelle: "Sahih al-Buchari, Nr. 125 und 4721; Sahih Muslim, Nr. 2794"}
],
begriffe: [
 {arab: "أَسْرَىٰ", tr: "asrā", wurzel: "s-r-y", erkl: "„Er ließ bei Nacht reisen“ – isrāʾ: die Nachtreise nach Jerusalem. Beachte: „Seinen Diener“ (ʿabdihī) – im höchsten Moment seiner Ehre wird der Prophet ﷺ ‚Diener' genannt. Dienerschaft ist der höchste Titel."},
 {arab: "الْمَسْجِد الْأَقْصَى", tr: "al-masdschid al-aqṣā", wurzel: "q-ṣ-w", erkl: "„Die fernste Moschee“ in Jerusalem – „deren Umgebung Wir gesegnet haben“. Die dritte heilige Stätte des Islam und die erste Gebetsrichtung (Qibla). Der Prophet ﷺ: Man soll nur zu drei Moscheen eigens reisen – al-Masdschid al-Ḥarām, seiner Moschee und al-Aqṣā (Sahih al-Buchari, Nr. 1189)."},
 {arab: "أُفٍّ", tr: "uff", wurzel: "–", erkl: "„Uff“ (17:23): „Sag nicht ‚uff' zu ihnen (den Eltern) und fahre sie nicht an.“ Das kleinste Geräusch der Genervtheit ist bereits verboten. Wenn schon das verboten ist – wie erst Schlimmeres."},
 {arab: "جَنَاحَ الذُّلِّ", tr: "dschanāḥ adh-dhull", wurzel: "dsch-n-ḥ / dh-l-l", erkl: "„Den Flügel der Demut“ (17:24) – senke ihn vor deinen Eltern „aus Barmherzigkeit“, wie ein Vogel seine Flügel über die Jungen breitet. Und das Gebet: rabbi rḥamhumā kamā rabbayānī ṣaghīrā."},
 {arab: "مُبَذِّرِين", tr: "mubadhdhirīn", wurzel: "b-dh-r", erkl: "„Verschwender“ (17:27): „Die Verschwender sind Brüder der Satane.“ Tabdhīr: Geld für Sinnloses oder Verbotenes ausstreuen (wie Saat in den Wind). Das Gegenmodell: weder geizig noch maßlos (17:29, vgl. 25:67 in Lektion 42)."},
 {arab: "كَرَّمْنَا بَنِي آدَم", tr: "karramnā banī Ādam", wurzel: "k-r-m", erkl: "„Wir haben die Kinder Ādams geehrt“ (17:70) – Grundlage der Menschenwürde im Islam: Jeder Mensch, unabhängig von Religion und Herkunft, hat eine von Allah verliehene Würde."},
 {arab: "الرُّوح", tr: "ar-rūḥ", wurzel: "r-w-ḥ", erkl: "Der Geist (17:85): „Der Geist gehört zur Angelegenheit meines Herrn; und euch ist vom Wissen nur wenig gegeben.“ Demut des Wissens: Nicht alles ist menschlich erfassbar (vgl. Glossar)."}
],
tafsir: [
 {vers: "Verse 1–22: Nachtreise und Lehren der Geschichte", text: "Die Nachtreise „um ihm etwas von Unseren Zeichen zu zeigen“; dann Mūsās Buch und die zweimalige Verderbnis der Kinder Israels. 17:9: „Dieser Koran leitet zu dem, was am richtigsten ist.“ 17:11: „Der Mensch ruft das Böse herbei, wie er das Gute herbeiruft – der Mensch ist eilig.“ 17:13–14: „Jedem Menschen haben Wir sein Schicksal an den Hals gehängt … Lies dein Buch! Du selbst genügst heute als Abrechner gegen dich.“ 17:15: „Wir strafen nicht, bevor Wir einen Gesandten geschickt haben“ – Grundlage der Lehre, dass niemand bestraft wird, den die Botschaft nicht erreichte. 17:18–21: Wer nur das Diesseits will, bekommt davon, was Allah will – wer das Jenseits will und sich dafür müht, dessen Mühe wird gedankt."},
 {vers: "Verse 22–39: die Lebensregeln", text: "Ibn ʿAbbās sagte, diese Verse seien die ‚Tafeln' (vergleichbar dem, was Mūsā erhielt). Die Reihenfolge ist Programm: Tauhīd (22–23), Eltern (23–25: „Sag nicht uff“, „sprich zu ihnen ehrerbietige Worte“, „senke den Flügel der Demut“, das Gebet für sie), Rechte der Verwandten, Armen, Reisenden, aber ohne Verschwendung (26–27); freundliche Worte, wenn man nichts geben kann (28); Maß beim Ausgeben (29); Versorgung liegt bei Allah (30); keine Kinder aus Furcht vor Armut töten – „Wir versorgen sie und euch“ (31; vgl. Lektion 7); „nähert euch nicht der Unzucht“ (32 – nicht nur verboten, sondern alles, was hinführt); kein Töten außer nach Recht (33); das Gut der Waise schützen (34); Versprechen halten (34); richtig messen (35); „folge nicht dem, wovon du kein Wissen hast – Gehör, Gesicht und Herz, über all das wird man befragt werden“ (36); nicht hochmütig gehen – „du kannst die Erde nicht durchbrechen und die Berge an Höhe nicht erreichen“ (37). As-Saʿdī: Eine vollständige Ethik in sechzehn Versen – vom Gottesdienst bis zum Gang auf der Straße."},
 {vers: "Verse 40–72: Koran, Gebet und Würde", text: "Wer Allah Töchter zuschreibt, sagt Gewaltiges; „die sieben Himmel und die Erde preisen Ihn … doch ihr versteht ihr Preisen nicht“ (44). Wenn der Prophet ﷺ den Koran liest, legt sich ein unsichtbarer Vorhang zwischen ihn und die Leugner (45). 17:53: „Sag Meinen Dienern, sie sollen das sagen, was am besten ist – der Satan stiftet Zwietracht zwischen ihnen“ – eine Grundregel für jede Diskussion unter Muslimen. Dann die Geschichte von Iblīs' Weigerung und seine Drohung, „mit deiner Stimme“ (Verführung) und „deinen Reitern und Fußtruppen“ die Menschen zu verführen – „über Meine Diener hast du keine Macht“ (65). 17:70: die Würde aller Kinder Ādams."},
 {vers: "Verse 73–100: Standhaftigkeit und Gebetszeiten", text: "Die Quraisch hätten den Propheten ﷺ beinahe zu Zugeständnissen verleitet – „hätten Wir dich nicht gefestigt“ (73–75; vgl. Lektion 18). 17:78–79: „Verrichte das Gebet vom Neigen der Sonne bis zum Dunkel der Nacht und den Koran der Morgendämmerung (qurʾān al-fadschr) – der Koran der Morgendämmerung wird bezeugt“ (die Engel der Nacht und des Tages wechseln beim Fadschr, Sahih al-Buchari, Nr. 4717); und das Nachtgebet als freiwillige Zugabe, „vielleicht wird dich dein Herr zu einer löblichen Stellung (maqām maḥmūd) erwecken“ – nach den Hadithen die große Fürsprache am Jüngsten Tag. 17:80: das Hidschra-Gebet: „Mein Herr, lass mich wahrhaftig eintreten und wahrhaftig hinausgehen.“ 17:81: „Die Wahrheit ist gekommen, und das Falsche ist vergangen“ – rezitiert vom Propheten ﷺ beim Zerschlagen der Götzen am Tag der Eroberung Mekkas (Sahih al-Buchari, Nr. 4720). 17:82: Der Koran ist „Heilung und Barmherzigkeit für die Gläubigen“. 17:85: der Geist. 17:88: Die Herausforderung: Menschen und Dschinn zusammen könnten nichts Gleiches hervorbringen."},
 {vers: "Verse 101–111: Mūsā, Wissende und Sadschda", text: "Mūsās neun Zeichen und Pharaos Ende. Dann: Der Koran ist in Abschnitte geteilt, „damit du ihn den Menschen mit Bedacht vorträgst“ (106 – die Begründung der stückweisen Offenbarung, vgl. Lektion 42). 17:107–109: „Diejenigen, denen zuvor Wissen gegeben wurde, fallen, wenn er ihnen vorgetragen wird, auf ihr Kinn nieder in Anbetung … und sie fallen weinend nieder, und er mehrt ihre Demut.“ Hier liegt die Sadschda-Stelle (17:109). Schluss: „Ruft Allah oder ruft den Allerbarmer – wie ihr auch ruft, Ihm gehören die schönsten Namen“; „sprich dein Gebet nicht zu laut und nicht zu leise, sondern suche einen Weg dazwischen“ (110); und das Lob: „Allahu akbar – Er ist größer“ (111: wa-kabbirhu takbīrā)."}
],
ahadith: [
 {text: "Der Bericht über Nachtreise und Himmelfahrt: der Burāq, das Gebet mit den Propheten in Jerusalem, der Aufstieg durch die sieben Himmel, die Auferlegung der fünfzig Gebete, verringert auf fünf – „fünf, und sie wiegen fünfzig“.", quelle: "Sahih al-Buchari, Nr. 349; Sahih Muslim, Nr. 162"},
 {text: "„Die Zufriedenheit des Herrn liegt in der Zufriedenheit des Vaters, und Sein Zorn im Zorn des Vaters.“ / „Er reibe seine Nase im Staub, er reibe seine Nase im Staub – wer seine Eltern oder einen von ihnen im Alter erlebt und dann nicht ins Paradies kommt.“", quelle: "Sunan at-Tirmidhī, Nr. 1899 (sahih); Sahih Muslim, Nr. 2551"},
 {text: "Der Prophet ﷺ schlief nicht ein, bevor er Banī Isrāʾīl (Al-Isrāʾ) und az-Zumar rezitiert hatte.", quelle: "Sunan at-Tirmidhī, Nr. 2920; hasan"},
 {text: "Am Tag der Eroberung Mekkas stieß der Prophet ﷺ die Götzen um die Kaaba mit einem Stock und sprach: „Die Wahrheit ist gekommen, und das Falsche ist vergangen“ (17:81).", quelle: "Sahih al-Buchari, Nr. 4720; Sahih Muslim, Nr. 1781"}
],
hanafi: "Zwei hanafitische Punkte: (1) 17:109 ist eine der 14 Sadschda-Stellen – die Rezitations-Niederwerfung ist hier wādschib. (2) Zu 17:110 („nicht zu laut und nicht zu leise“) regelt die Schule die Lautstärke der Rezitation im Gebet: Der Imam rezitiert laut (dschahr) in Fadschr, den ersten beiden Rakʿa von Maghrib und ʿIschāʾ sowie im Freitags- und Festgebet; leise (sirr) in Ẓuhr und ʿAṣr. Wer allein betet, darf in den lauten Gebeten wählen. Wird die Lautstärke-Regel versehentlich verletzt, ist nach der Schule die Vergesslichkeitsniederwerfung (sadschdat as-sahw) fällig. Außerdem zu 17:78: Hanafitisch ist es empfohlen, das Fadschr-Gebet zu verrichten, wenn es bereits etwas hell geworden ist (isfār).",
umsetzung: [
 "Lerne das Elterngebet 17:24 (rabbi rḥamhumā kamā rabbayānī ṣaghīrā) und sprich es nach jedem Gebet – und streiche diese Woche jedes genervte ‚uff' gegenüber deinen Eltern.",
 "Nimm 17:22–39 als Monatsprogramm: Jeden Tag eine der Regeln bewusst leben. Am Ende des Monats: Welche fällt mir am schwersten?",
 "Wende 17:36 auf deinen Medienkonsum an: Nichts weiterleiten, nichts glauben, nichts nachplappern, wovon du kein gesichertes Wissen hast – Ohr, Auge und Herz werden befragt.",
 "Führe 17:53 in Diskussionen ein: Sag immer das Beste, gerade unter Muslimen. Der Satan lebt von Zwietracht.",
 "Mach die Tilāwa-Sadschda bei 17:109 (hanafitisch wādschib) und lies Al-Isrāʾ wie der Prophet ﷺ vor dem Schlafen – zumindest einmal pro Woche."
]
},

// ───────────────────────── Lektion 51: Yūnus ─────────────────────────
{
sure: 10, offb: 51, name: "Yūnus", arab: "سُورَةُ يُونُسَ", de: "Jona", verse: 109, ort: "Mekka",
zeit: "Spätmekkanisch – eine Sure über Allahs Geduld und die offene Tür zur Umkehr",
kurz: "Die Sure trägt den Namen eines Propheten, dessen Geschichte darin nur einen Vers einnimmt – aber was für einen: Das Volk von Yūnus ist das einzige Volk der Geschichte, das umkehrte, als die Strafe schon sichtbar war, und gerettet wurde (10:98). Das ist der rote Faden der Sure: Allah ist geduldig, Seine Tür steht offen, aber man darf nicht warten, bis es zu spät ist – wie Pharao, der erst im Ertrinken sagte „Ich glaube“ und hören musste: „Jetzt? Wo du vorher ungehorsam warst?“ Dazu der Trost für die Freunde Allahs: „Gewiss, über die Freunde Allahs kommt keine Furcht, und sie werden nicht traurig sein.“ Und die Einladung: „Über die Huld Allahs und Seine Barmherzigkeit – darüber sollen sie sich freuen.“",
schluessel: {arab: "أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", ueb: "Gewiss, über die Freunde Allahs kommt keine Furcht, und sie werden nicht traurig sein.", ref: "10:62"},
kontext: ["Yūnus eröffnet eine Gruppe von sechs Suren, die mit den Buchstaben Alif-Lām-Rā beginnen (Yūnus, Hūd, Yūsuf, Ar-Raʿd, Ibrāhīm, Al-Ḥidschr) und in derselben spätmekkanischen Phase stehen. Sie alle sprechen in eine Zeit, in der die Gemeinde unter Boykott und Verfolgung stand und viele fragten: Warum straft Allah die Unterdrücker nicht endlich? Die Antwort von Yūnus: Allahs Aufschub ist Geduld – und Chance, auch für die Gegner.",
"Die Yūnus-Geschichte selbst (vollständiger in 21:87 und 37:139–148): Yūnus verließ sein Volk zornig, bevor Allah es ihm erlaubte, wurde vom Fisch verschluckt und betete in dreifacher Dunkelheit: „Es gibt keinen Gott außer Dir, gepriesen seist Du, ich gehöre zu den Ungerechten“ (21:87). Sein Volk aber – das er verlassen hatte – kehrte um, als es die Zeichen der Strafe sah, und „Wir nahmen von ihnen die Strafe der Schande im diesseitigen Leben“ (10:98). Eine doppelte Lehre: Gib Menschen nie zu früh auf, und Allahs Barmherzigkeit kann sogar die angekündigte Strafe abwenden.",
"Die Sure enthält eine der deutlichsten Aussagen über Glaubensfreiheit: „Wenn dein Herr wollte, würden alle auf der Erde glauben. Willst du etwa die Menschen dazu zwingen, gläubig zu werden?“ (10:99; vgl. Brennpunkt 2:256). Iman lässt sich nicht erzwingen – nur einladen."],
asbab: ["Für Yūnus ist kein spezifischer Offenbarungsanlass sahih überliefert. Zu 10:2 („Ist es für die Menschen verwunderlich, dass Wir einem Mann von ihnen offenbart haben?“) berichten die Tafsir-Werke, die Quraisch hätten es unmöglich gefunden, dass Allah einen Menschen – ein Waisenkind ohne Vermögen – als Gesandten schickt (Ibn Kathīr z. St., Bericht von Ibn ʿAbbās; nicht in Buchari/Muslim)."],
begriffe: [
 {arab: "أَوْلِيَاء اللَّه", tr: "auliyāʾ Allāh", wurzel: "w-l-y", erkl: "„Die Freunde/Vertrauten Allahs“ – 10:63 definiert sie sofort: „diejenigen, die glauben und gottesfürchtig sind“. Kein Geheimbund und keine Wundertäter-Elite, sondern jeder Gläubige mit Taqwā – in verschiedenen Stufen."},
 {arab: "الْحُسْنَىٰ وَزِيَادَة", tr: "al-ḥusnā wa-ziyāda", wurzel: "ḥ-s-n / z-y-d", erkl: "„Das Schönste und noch mehr“ (10:26): Das Schönste ist das Paradies – das ‚Mehr' ist nach dem Hadith (Muslim 181, vgl. Lektion 34) der Blick auf Allahs Angesicht."},
 {arab: "شِفَاءٌ لِّمَا فِي الصُّدُور", tr: "schifāʾun limā fī ṣ-ṣudūr", wurzel: "sch-f-y", erkl: "„Heilung für das, was in den Brüsten ist“ (10:57) – der Koran heilt Zweifel, Begierden, Angst und Trauer. Vier Eigenschaften in einem Vers: Ermahnung, Heilung, Rechtleitung, Barmherzigkeit."},
 {arab: "فَلْيَفْرَحُوا", tr: "fa-l-yafraḥū", wurzel: "f-r-ḥ", erkl: "„… darüber sollen sie sich freuen“ (10:58) – über Allahs Huld und Barmherzigkeit, sprich: über den Islam und den Koran. „Das ist besser als das, was sie anhäufen.“ Freude am Glauben ist ein Gebot, keine Nebensache."},
 {arab: "آلْآنَ", tr: "āl-āna", wurzel: "–", erkl: "„Jetzt (erst)?“ (10:91) – Allahs Antwort auf Pharaos Glaubensbekenntnis im Ertrinken. Tauba ist bis zum letzten Atemzug offen – aber nicht mehr, wenn der Tod sichtbar geworden ist (vgl. 4:18). Das Wort ist eine Warnung gegen das Aufschieben."},
 {arab: "قَوْم يُونُس", tr: "qaum Yūnus", wurzel: "–", erkl: "Das Volk von Yūnus (10:98): das einzige Volk, dessen kollektive Reue im Angesicht der Strafe angenommen wurde. Der Beweis, dass Allah lieber vergibt als straft."}
],
tafsir: [
 {vers: "Verse 1–25: der Mensch in Not und Wohlstand", text: "Die Quraisch wundern sich, dass ein Mensch Gesandter ist. Dann Allahs Schöpfung: Sonne als Leuchte, Mond als Licht mit Stationen „damit ihr die Zahl der Jahre und die Berechnung wisst“. 10:12 zeichnet den Menschen präzise: „Wenn dem Menschen Schaden widerfährt, ruft er Uns an – auf der Seite liegend, sitzend oder stehend. Wenn Wir ihm dann den Schaden hinwegnehmen, geht er vorbei, als hätte er Uns nie wegen eines Schadens angerufen.“ 10:22–23 das Bild vom Schiff im Sturm: Alle beten aufrichtig – kaum sind sie gerettet, sind sie wieder ungerecht. 10:24 das Gleichnis der Dunya: wie Regen, der Pflanzen sprießen lässt, die Erde schmückt sich – und plötzlich ist alles abgemäht, „als wäre es gestern nicht gewesen“. Und dagegen 10:25: „Allah ruft zur Wohnstätte des Friedens (dār as-salām).“"},
 {vers: "Verse 26–70: Wahrheit und Freundschaft mit Allah", text: "10:26: das Schönste und noch mehr. Die Götzen werden sich am Jüngsten Tag von ihren Anbetern lossagen. 10:32: „Was gibt es nach der Wahrheit anderes als den Irrtum?“ 10:37–38: die Herausforderung, eine einzige Sure wie diese zu bringen. 10:57–58: der Koran als Heilung und die Pflicht zur Freude darüber. 10:61: Allah sieht jede Tätigkeit, „nicht entgeht deinem Herrn das Gewicht eines Stäubchens“. Dann 10:62–64: die Freunde Allahs ohne Furcht und Trauer, „für sie ist die frohe Botschaft im diesseitigen Leben und im Jenseits“ – nach dem Hadith gehört dazu der gute Traum, den ein Gläubiger sieht oder der für ihn gesehen wird (Sunan at-Tirmidhī, Nr. 2273; sahih). Ibn Kathīr: Die Walāya ist die Frucht von Iman und Taqwā – wer beides pflegt, für den gilt die Zusage."},
 {vers: "Verse 71–93: Nūḥ, Mūsā und Pharaos zu spätes Bekenntnis", text: "Nūḥ fordert sein Volk heraus: „Beschließt eure Sache … dann trefft eure Entscheidung über mich und gewährt mir keinen Aufschub“ – Tawakkul ohne Angst. Mūsā vor Pharao; die Zauberer; die Gläubigen aus Mūsās Volk beten: „Unser Herr, mach uns nicht zu einer Versuchung für das ungerechte Volk“ (10:85) – ein Duʿā für jede verfolgte Minderheit. 10:87: „Macht eure Häuser zu Gebetsstätten“ – wenn der öffentliche Raum versperrt ist, wird das Haus zur Moschee. Dann der Durchzug, und Pharao im Ertrinken: „Ich glaube, dass es keinen Gott gibt außer Dem, an Den die Kinder Israels glauben.“ – „Jetzt? Wo du vorher ungehorsam warst? Heute retten Wir deinen Leib, damit du für die Späteren ein Zeichen bist.“ Al-Qurṭubī: Der Leichnam als Zeichen – der Tyrann, der sich Gott nannte, endet als angeschwemmter Körper."},
 {vers: "Verse 94–109: das Volk von Yūnus und kein Zwang", text: "10:98: „Warum gab es keine Stadt, die glaubte, sodass ihr Glaube ihr nützte – außer dem Volk von Yūnus? Als sie glaubten, nahmen Wir von ihnen die Strafe der Schande im diesseitigen Leben.“ 10:99–100: kein Zwang zum Glauben. 10:107: „Wenn Allah dich mit Schaden trifft, kann ihn niemand hinwegnehmen außer Ihm; und wenn Er dir Gutes will, kann niemand Seine Huld zurückweisen“ (vgl. 35:2, Lektion 43). Schluss: „Folge dem, was dir offenbart wird, und sei geduldig, bis Allah richtet. Er ist der beste Richter.“ As-Saʿdī: Die Sure, die mit dem Staunen der Leugner begann, endet mit Geduld – das ist die Haltung, die die Gemeinde durch die letzten mekkanischen Jahre trug."}
],
ahadith: [
 {text: "Hadith Qudsi: „Wer einem Meiner Freunde (walī) feind ist, dem erkläre Ich den Krieg. Mein Diener nähert sich Mir mit nichts, das Mir lieber wäre, als mit dem, was Ich ihm zur Pflicht gemacht habe; und Mein Diener hört nicht auf, sich Mir mit freiwilligen Taten zu nähern, bis Ich ihn liebe …“ – der Weg zur Walāya von 10:62.", quelle: "Sahih al-Buchari, Nr. 6502"},
 {text: "Das Gebet des Yūnus im Bauch des Fisches: „Lā ilāha illā anta, subḥānaka, innī kuntu mina ẓ-ẓālimīn“ – „Kein Muslim bittet damit um etwas, ohne dass Allah ihm antwortet.“", quelle: "Sunan at-Tirmidhī, Nr. 3505; sahih"},
 {text: "„Allah nimmt die Reue des Dieners an, solange er nicht röchelt (im Todeskampf).“ – zu Pharaos ‚Jetzt?'.", quelle: "Sunan at-Tirmidhī, Nr. 3537; hasan"},
 {text: "Zur frohen Botschaft im Diesseits (10:64): „Es ist der gute Traum, den der Muslim sieht oder der für ihn gesehen wird.“", quelle: "Sunan at-Tirmidhī, Nr. 2273; sahih"}
],
hanafi: null,
umsetzung: [
 "Lerne das Duʿā des Yūnus (lā ilāha illā anta subḥānaka innī kuntu mina ẓ-ẓālimīn) und sprich es in jeder Krise – mit der Zusage aus Tirmidhī 3505.",
 "Wende 10:12 auf dich an: Erinnere dich an eine Notlage, in der du intensiv gebetet hast. Betest du heute noch genauso? Dank in der Fülle ist die Probe der Aufrichtigkeit in der Not.",
 "Freu dich bewusst an deinem Glauben (10:58): Nimm dir einmal pro Woche Zeit, Allah konkret für den Islam, den Koran und deinen Weg zu danken.",
 "Gib niemanden zu früh auf (10:98): Bete für den Menschen in deinem Umfeld, der am weitesten weg scheint. Auch das Volk von Yūnus kehrte im letzten Moment um.",
 "Schieb Tauba nicht auf (10:91): Was du bereuen musst, bereue heute – nicht ‚wenn ich älter bin'."
]
},

// ───────────────────────── Lektion 52: Hūd ─────────────────────────
{
sure: 11, offb: 52, name: "Hūd", arab: "سُورَةُ هُودٍ", de: "Hūd", verse: 123, ort: "Mekka",
zeit: "Spätmekkanisch – im Jahr der Trauer, als der Prophet ﷺ die schwerste Zeit durchlebte",
kurz: "Die Sure, über die der Prophet ﷺ sagte: „Hūd hat mich grau werden lassen.“ Gefragt, was genau, nannten Gelehrte den Vers 112: „So sei standhaft, wie dir befohlen wurde.“ Istiqāma – geradlinig bleiben, ohne nach links oder rechts abzuweichen – ist das Thema der Sure. Sieben Prophetengeschichten zeigen, wie die Gesandten standhaft blieben: Nūḥ, der seinen eigenen Sohn in den Fluten verlor; Hūd, der ganz allein einem übermächtigen Volk sagte „Ich nehme Allah zum Zeugen“; Ṣāliḥ; Ibrāhīm, dessen Frau im hohen Alter lachte; Lūṭ in seiner Not; Schuʿaib, der sagte „Ich will nur Besserung, soweit ich kann“; und Mūsā. Und mitten in der Strenge die Barmherzigkeit: „Die guten Taten tilgen die schlechten.“",
schluessel: {arab: "فَاسْتَقِمْ كَمَا أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا", ueb: "So sei standhaft, wie dir befohlen wurde, (du) und wer mit dir umkehrt, und überschreitet nicht das Maß.", ref: "11:112"},
kontext: ["„Hūd und ihre Schwestern haben mich grau werden lassen“ (Sunan at-Tirmidhī, Nr. 3297; vgl. Lektion 46). Ibn ʿAbbās sagte: „Auf den Gesandten Allahs ﷺ wurde kein Vers herabgesandt, der härter und schwerer für ihn war als dieser Vers: ‚So sei standhaft, wie dir befohlen wurde.'“ (Bericht in den Tafsir-Werken, u. a. bei al-Baghawī und al-Qurṭubī). Der Grund: Istiqāma ist das Schwerste – nicht ein großer Kraftakt, sondern jeden Tag, in jeder Kleinigkeit, genau auf der Linie bleiben.",
"Die Sure fällt in die Zeit nach dem Tod Abū Ṭālibs und Chadīdschas, kurz vor oder nach Ṭāʾif. Der Prophet ﷺ hatte seinen Beschützer und seine engste Vertraute verloren. Die Prophetengeschichten sind hier als Spiegel erzählt: Nūḥ verlor seinen Sohn, Lūṭ stand allein gegen die ganze Stadt („Hätte ich doch Kraft gegen euch oder könnte zu einem starken Halt Zuflucht nehmen!“), Schuʿaib wurde verspottet („Befiehlt dir dein Gebet …?“). Allah sagt am Ende (11:120): „Alles, was Wir dir von den Geschichten der Gesandten erzählen, ist das, womit Wir dein Herz festigen.“",
"Hūd und Yūsuf wurden nach Überlieferungen kurz hintereinander offenbart – erst die Strenge, dann der Trost. Wer Hūd liest, versteht, warum Yūsuf „die schönste Geschichte“ heißen musste."],
asbab: [
 {text: "11:114 („Verrichte das Gebet an beiden Enden des Tages und in Stunden der Nacht. Die guten Taten tilgen die schlechten“): Ein Mann hatte eine fremde Frau geküsst, kam reuig zum Propheten ﷺ und berichtete es. Da kam dieser Vers herab. Der Mann fragte: „Gilt das nur für mich?“ – „Für meine ganze Umma.“", quelle: "Sahih al-Buchari, Nr. 526; Sahih Muslim, Nr. 2763"}
],
begriffe: [
 {arab: "اسْتَقِمْ", tr: "istaqim", wurzel: "q-w-m", erkl: "„Sei standhaft/gerade“ – Istiqāma: auf dem geraden Weg (ṣirāṭ mustaqīm, Lektion 5) bleiben, ohne Übertreibung und ohne Nachlassen. Der Zusatz „kamā umirta – wie dir befohlen wurde“ schließt beides aus: nicht mehr, nicht weniger."},
 {arab: "لَا تَطْغَوْا", tr: "lā taṭġau", wurzel: "ṭ-ġ-y", erkl: "„Überschreitet nicht das Maß“ – direkt nach dem Befehl zur Standhaftigkeit. Al-Qurṭubī: Übertreibung im Dīn ist auch eine Abweichung von der Istiqāma (vgl. ṭaġā in Lektion 1)."},
 {arab: "تَرْكَنُوا", tr: "tarkanū", wurzel: "r-k-n", erkl: "11:113: „Neigt euch nicht den Ungerechten zu, sonst berührt euch das Feuer.“ Rukūn: sich anlehnen, Vertrauen schenken. Schon die innere Anlehnung an Unrechtstäter ist gefährlich."},
 {arab: "الْحَسَنَات يُذْهِبْنَ السَّيِّئَات", tr: "al-ḥasanāt yudhhibna s-sayyiʾāt", wurzel: "ḥ-s-n / s-w-ʾ", erkl: "„Die guten Taten tilgen die schlechten“ (11:114) – nach den Gelehrten vor allem die kleinen Sünden; große brauchen ausdrückliche Tauba. Ein Hoffnungsvers mit klarem Anlass (Buchari 526)."},
 {arab: "الْإِصْلَاح", tr: "al-iṣlāḥ", wurzel: "ṣ-l-ḥ", erkl: "„Besserung/Verbesserung“ – Schuʿaibs Programm (11:88): „Ich will nur Besserung, soweit ich kann. Mein Gelingen (taufīq) liegt allein bei Allah.“ Das Motto jedes ehrlichen Reformers."},
 {arab: "لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا", tr: "li-yabluwakum ayyukum aḥsanu ʿamalā", wurzel: "b-l-w", erkl: "11:7: Allah erschuf Himmel und Erde, „um euch zu prüfen, wer von euch die beste Tat tut“ – nicht die meisten Taten, sondern die besten (aufrichtig und richtig, so al-Fuḍail ibn ʿIyāḍ)."}
],
tafsir: [
 {vers: "Verse 1–24: Programm und Mensch", text: "Ein Buch, „dessen Verse fest gefügt und dann ausführlich dargelegt sind“, mit der Kernbotschaft: Dient nur Allah, bittet um Vergebung, kehrt um – dann gibt Er euch schönen Genuss bis zu einer Frist (11:2–3). 11:6: „Es gibt kein Lebewesen auf der Erde, dessen Versorgung nicht Allah obläge.“ 11:7: die Schöpfung als Prüfung, wer die beste Tat tut. 11:9–11: der Mensch, verzweifelt im Entzug, prahlend im Wohlstand – „außer denen, die geduldig sind und rechtschaffene Werke tun“. As-Saʿdī: Geduld in der Not und Bescheidenheit im Glück sind dieselbe Tugend in zwei Kleidern."},
 {vers: "Verse 25–49: Nūḥ und sein Sohn", text: "Nūḥs Volk verachtet seine Anhänger als „die Niedrigsten“; er weigert sich, sie wegzustoßen. Der Bau der Arche unter Spott („Jedes Mal, wenn die Vornehmen seines Volkes an ihm vorbeigingen, verspotteten sie ihn“). Dann die Flut, „Wogen wie Berge“, und der Sohn, der abseits steht. Nūḥ ruft: „O mein Söhnchen, steig mit uns ein!“ – „Ich werde auf einem Berg Zuflucht suchen.“ – „Heute gibt es keinen Schutz vor Allahs Befehl“ – und die Woge trennt sie. Nūḥ betet: „Mein Sohn gehört doch zu meiner Familie!“ – „Er gehört nicht zu deiner Familie; es war eine Handlung, die nicht rechtschaffen war.“ Ibn Kathīr: Die Familie des Glaubens ist stärker als die Familie des Blutes – und doch verschweigt der Koran den Vaterschmerz nicht. Nūḥ bittet sofort um Vergebung für seine Bitte. 11:49: „Sei geduldig – das (gute) Ende gehört den Gottesfürchtigen.“"},
 {vers: "Verse 50–83: Hūd, Ṣāliḥ, Ibrāhīm, Lūṭ", text: "Hūd zu ʿĀd: „Bittet euren Herrn um Vergebung, dann kehrt zu Ihm um – Er schickt euch reichlich Regen und mehrt eure Kraft“ (11:52; vgl. Nūḥ in 71:10–12). Allein gegen alle: „Ich nehme Allah zum Zeugen … so schmiedet alle zusammen eine List gegen mich – ich verlasse mich auf Allah. Es gibt kein Lebewesen, das Er nicht an seinem Schopf hält“ (11:54–56). Ṣāliḥ und die Kamelstute. Dann die Engel bei Ibrāhīm: Er bringt ihnen sofort ein gebratenes Kalb (Gastfreundschaft), sie essen nicht, er erschrickt; seine Frau lacht über die Ankündigung eines Sohnes im hohen Alter: „Wundert ihr euch über Allahs Befehl?“ Ibrāhīm streitet sogar für das Volk Lūṭs – „Ibrāhīm war wahrlich nachsichtig, voller Mitgefühl, (immer) umkehrend“ (11:75). Dann Lūṭs Not mit seinem Volk und die Rettung im letzten Teil der Nacht: „Ist der Morgen nicht nahe?“"},
 {vers: "Verse 84–110: Schuʿaib und Mūsā", text: "Schuʿaib zu Madyan: volles Maß, keine Benachteiligung. Die Antwort ist zeitlos: „O Schuʿaib, befiehlt dir dein Gebet, dass wir lassen sollen, was unsere Väter anbeteten, oder dass wir mit unserem Besitz nicht tun, was wir wollen?“ (11:87) – das Gebet als Einmischung in die Wirtschaft? Genau das, sagt der Koran: Wer betet, kann nicht betrügen. Schuʿaibs Antwort 11:88: „Ich will euch nicht widersprechen, um selbst zu tun, was ich euch verbiete; ich will nur Besserung, soweit ich kann; und mein Gelingen kommt nur durch Allah.“ Dann Pharao, der seinem Volk am Jüngsten Tag vorangeht – „ins Feuer“."},
 {vers: "Verse 111–123: Istiqāma und Trost", text: "Der Kernvers 11:112, dann 11:113 (nicht zu den Ungerechten neigen), 11:114 (Gebet und Tilgung der Sünden, mit dem Anlass), 11:115 (Geduld). 11:116–117: Warum gab es unter den früheren Generationen nicht mehr Leute, die gegen das Unheil auf der Erde einschritten? Und: „Dein Herr vernichtet keine Städte zu Unrecht, solange ihre Bewohner (um) Besserung (bemüht) sind (muṣliḥūn)“ – nicht nur ‚gut' (ṣāliḥūn), sondern Verbesserer. 11:118–119: Allah hätte die Menschen zu einer einzigen Gemeinschaft machen können; sie bleiben uneinig, „außer denen, derer sich dein Herr erbarmt“. 11:120: die Geschichten festigen das Herz. Schluss: „Ihm gehört das Verborgene … so diene Ihm und verlass dich auf Ihn.“"}
],
ahadith: [
 {text: "Abū Bakr: „O Gesandter Allahs, du bist grau geworden!“ – „Hūd, al-Wāqiʿa, al-Mursalāt, ʿAmma yatasāʾalūn und Idhā sch-schamsu kuwwirat haben mich grau werden lassen.“", quelle: "Sunan at-Tirmidhī, Nr. 3297; hasan"},
 {text: "Der Mann, der eine fremde Frau geküsst hatte, und die Herabsendung von 11:114 – „für meine ganze Umma“.", quelle: "Sahih al-Buchari, Nr. 526; Sahih Muslim, Nr. 2763"},
 {text: "Sufyān ibn ʿAbdillāh bat: „Sag mir über den Islam ein Wort, nach dem ich niemanden mehr fragen muss.“ – „Sag: Ich glaube an Allah – dann sei standhaft (thumma staqim).“", quelle: "Sahih Muslim, Nr. 38"},
 {text: "„Die fünf Gebete und von Freitag zu Freitag sind Sühne für das, was dazwischen liegt, solange die großen Sünden gemieden werden.“ – zu 11:114.", quelle: "Sahih Muslim, Nr. 233"}
],
hanafi: "Zu 11:114 („an beiden Enden des Tages und in Stunden der Nacht“) sehen die Mufassirūn einen frühen Hinweis auf die Gebetszeiten (Fadschr, Ẓuhr/ʿAṣr, Maghrib/ʿIschāʾ). Hanafitische Besonderheiten bei den Zeiten: Die ʿAṣr-Zeit beginnt nach der Schulmeinung Abū Ḥanīfas, wenn der Schatten eines Gegenstands doppelt so lang ist wie er selbst (zuzüglich des Mittagsschattens) – später als bei den anderen Schulen; viele Kalender für Hanafiten zeigen deshalb einen eigenen „ʿAṣr (Hanafi)“-Zeitpunkt. Außerdem empfiehlt die Schule, ʿAṣr nicht zu früh, aber vor dem Gelbwerden der Sonne zu beten. Und zum Inhalt des Verses: Gute Taten tilgen nach der Schule (wie nach der Mehrheit) die kleinen Sünden; für große Sünden ist ausdrückliche Tauba nötig.",
umsetzung: [
 "Mach thumma staqim (Muslim 38) zu deinem Lebensmotto: Wähle EINE gute Gewohnheit und halte sie 40 Tage ohne Unterbrechung – Istiqāma wird nicht in großen Sprüngen gelernt, sondern in täglicher Treue.",
 "Wenn du gesündigt hast: bereue und tu sofort danach eine gute Tat – „die guten Taten tilgen die schlechten“. Der Mann aus Buchari 526 kam zum Propheten ﷺ, nicht weg von ihm.",
 "Prüfe deine Neigungen (11:113): Bei wem lehnst du dich an, obwohl er offen Unrecht tut – aus Bequemlichkeit, Karriere oder Angst?",
 "Werde muṣliḥ (11:117): nicht nur selbst gut sein, sondern im Umfeld verbessern – Schuʿaibs Motto „Besserung, soweit ich kann“ ohne Größenwahn.",
 "Lies die Sure Hūd einmal in Ruhe und dann Yūsuf direkt hinterher – so, wie sie offenbart wurden: erst die Strenge, dann der Trost."
]
},

// ───────────────────────── Lektion 53: Yūsuf ─────────────────────────
{
sure: 12, offb: 53, name: "Yūsuf", arab: "سُورَةُ يُوسُفَ", de: "Josef", verse: 111, ort: "Mekka",
zeit: "Spätmekkanisch – im ‚Jahr der Trauer', als Trost für den Propheten ﷺ",
kurz: "„Wir erzählen dir die schönste der Geschichten“ – die einzige Sure, die eine einzige Geschichte vollständig von Anfang bis Ende erzählt. Ein Junge träumt, dass sich elf Sterne, Sonne und Mond vor ihm verneigen. Seine eifersüchtigen Brüder werfen ihn in einen Brunnen, er wird als Sklave verkauft, von der Frau seines Herrn verführt – „Mein Herr, das Gefängnis ist mir lieber“ –, unschuldig eingesperrt, deutet Träume, wird Schatzmeister Ägyptens und steht am Ende vor seinen Brüdern, die ihn nicht erkennen. Er hätte sich rächen können. Er sagt: „Kein Tadel über euch heute. Allah vergibt euch.“ Und sein Vater Yaʿqūb, blind vor Trauer, sagt die ganze Zeit nur: „Schöne Geduld (ṣabrun dschamīl).“ Die Sure ist Trost für jeden, der verraten, verkannt oder verloren ist: Allah hat einen Plan, auch wenn du ihn nicht siehst.",
schluessel: {arab: "إِنَّهُ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ", ueb: "Wer gottesfürchtig und geduldig ist – Allah lässt den Lohn der Gutes Tuenden nicht verloren gehen.", ref: "12:90"},
kontext: ["Die Sure kam in der dunkelsten Zeit Mekkas: Chadīdscha und Abū Ṭālib waren gestorben, Ṭāʾif hatte den Propheten ﷺ mit Steinen vertrieben, die Quraisch planten bereits seine Vertreibung oder Ermordung. In diese Lage spricht eine Geschichte über einen Propheten, den die eigenen Brüder verrieten und aus der Heimat entfernten – und der am Ende als Mächtiger vor ihnen steht und vergibt. Die Parallele erfüllte sich wörtlich: Bei der Eroberung Mekkas acht Jahre später stand der Prophet ﷺ vor den Quraisch, die ihn vertrieben hatten, und nach der Sīra-Überlieferung zitierte er Yūsuf: „Kein Tadel über euch heute“ (12:92) – und gab eine Generalamnestie.",
"Nach einer Überlieferung (al-Ḥākim, von Saʿd ibn Abī Waqqāṣ) baten die Gefährten in dieser bedrückenden Zeit: „O Gesandter Allahs, würdest du uns (Geschichten) erzählen?“ – darauf kam die Sure herab: „Wir erzählen dir die schönste der Geschichten.“ Allah selbst wird zum Erzähler, wenn seine Diener Trost brauchen.",
"Yūsufs Geschichte ist durchgehend von zwei Kräften gesteuert: Menschen planen (die Brüder, die Frau des ʿAzīz, die Hofdamen) – und Allah plant über ihnen. Jede Intrige gegen Yūsuf wird zur Stufe nach oben: Der Brunnen bringt ihn nach Ägypten, die Verleumdung ins Gefängnis, das Gefängnis zum König. „Allah ist in Seiner Angelegenheit überlegen, doch die meisten Menschen wissen es nicht“ (12:21)."],
asbab: [
 {text: "Die Gefährten baten den Propheten ﷺ in einer Zeit der Bedrückung, ihnen etwas zu erzählen – darauf kam die Sure herab.", quelle: "al-Ḥākim, al-Mustadrak (von Saʿd ibn Abī Waqqāṣ; von ihm als sahih eingestuft); vgl. Ibn Kathīr zu 12:3"},
 {text: "Das Zitat von 12:92 („Kein Tadel über euch heute“) bei der Eroberung Mekkas ist ein bekannter Bericht der Sīra-Literatur (u. a. bei al-Baihaqī), nicht in Buchari/Muslim.", quelle: "Sīra-Überlieferung (Ibn Hischām; al-Baihaqī, Dalāʾil an-Nubuwwa)"}
],
begriffe: [
 {arab: "أَحْسَن الْقَصَص", tr: "aḥsan al-qaṣaṣ", wurzel: "q-ṣ-ṣ", erkl: "„Die schönste der Geschichten“ (12:3) – schön, weil wahr, vollständig, mit edlen Charakteren und einem Ende, das Barmherzigkeit über Rache stellt. Qaṣṣa heißt auch: einer Spur folgen – eine Geschichte, die man Schritt für Schritt nachgeht."},
 {arab: "صَبْرٌ جَمِيل", tr: "ṣabrun dschamīl", wurzel: "ṣ-b-r / dsch-m-l", erkl: "„Schöne Geduld“ (12:18, 12:83) – Yaʿqūbs Antwort auf zwei Verluste. Die Gelehrten: Geduld ohne Klage bei Menschen – Klage bei Allah ist erlaubt („Ich klage meinen Kummer und meine Trauer nur Allah“, 12:86). ʿĀʾischa zitierte diese Worte, als sie verleumdet wurde (Sahih al-Buchari, Nr. 4750)."},
 {arab: "رَاوَدَتْهُ", tr: "rāwadat-hu", wurzel: "r-w-d", erkl: "„Sie versuchte ihn zu verführen“ (12:23) – die Frau des ʿAzīz, bei verschlossenen Türen. Yūsufs Antwort: maʿādha llāh – „Allah bewahre!“ Der Koran beschreibt die Versuchung ohne Scham und ohne Ausschmückung – und Yūsufs Standhaftigkeit als Vorbild für jeden jungen Menschen."},
 {arab: "النَّفْس الْأَمَّارَة", tr: "an-nafs al-ammāra", wurzel: "ʾ-m-r", erkl: "„Die zum Bösen befehlende Seele“ (12:53): „Ich spreche meine Seele nicht frei; die Seele befiehlt das Böse, außer wessen sich mein Herr erbarmt.“ Die unterste der drei Seelenstufen (vgl. Lektion 10 und 31) – benannt von einem, der der Versuchung widerstand. Demut statt Selbstlob."},
 {arab: "لَا تَثْرِيبَ", tr: "lā tathrība", wurzel: "th-r-b", erkl: "„Kein Tadel“ (12:92): „Kein Tadel über euch heute. Allah vergibt euch.“ Tathrīb: Vorwürfe wiederholen, Wunden aufreißen. Yūsuf verzichtet sogar auf den Vorwurf – vollständige Vergebung ohne Nachtreten."},
 {arab: "لَطِيف", tr: "laṭīf", wurzel: "l-ṭ-f", erkl: "„Feinfühlig/der Feinwirkende“ (12:100): „Mein Herr ist feinfühlig in dem, was Er will.“ al-Laṭīf: Allah erreicht Seine Ziele auf so feinen, verborgenen Wegen, dass man sie erst im Rückblick erkennt."}
],
tafsir: [
 {vers: "Verse 1–20: Traum und Brunnen", text: "Der Traum mit elf Sternen, Sonne und Mond; Yaʿqūbs Rat: „Erzähl deinen Traum nicht deinen Brüdern, sonst schmieden sie eine List gegen dich“ (12:5 – Weisheit im Umgang mit Neid). Die Brüder: „Yūsuf und sein Bruder sind unserem Vater lieber als wir.“ Der Plan: töten oder in ein fernes Land werfen – „danach könnt ihr rechtschaffene Leute sein“ (12:9: Die Sünde wird mit späterer Reue eingeplant – eine gefährliche Selbsttäuschung, so Ibn Kathīr). Der Brunnen, das Hemd mit falschem Blut („Und sie kamen mit falschem Blut auf seinem Hemd“), Yaʿqūbs Antwort: ṣabrun dschamīl. Eine Karawane findet den Jungen und verkauft ihn „für einen geringen Preis, ein paar Dirham“. As-Saʿdī: Der wertvollste Mensch Ägyptens wurde für Kleingeld verkauft – der Wert eines Menschen liegt nicht im Marktpreis."},
 {vers: "Verse 21–35: Versuchung und Gefängnis", text: "Der ʿAzīz kauft ihn: „Mach seinen Aufenthalt angenehm, vielleicht nützt er uns.“ Yūsuf wächst heran, erhält Urteilskraft und Wissen. Dann die Versuchung bei verschlossenen Türen; 12:24: „Sie hatte es auf ihn abgesehen, und er hätte es auf sie abgesehen, hätte er nicht den Beweis seines Herrn gesehen“ – die Gelehrten: Er spürte die menschliche Neigung, widerstand ihr aber, und gerade darin liegt sein Rang. Das von hinten zerrissene Hemd beweist seine Unschuld. Die Hofdamen spotten, die Frau des ʿAzīz lädt sie ein, gibt ihnen Messer, Yūsuf tritt ein – sie schneiden sich in die Hände: „Das ist kein Mensch, das ist ein edler Engel!“ Yūsuf betet: „Mein Herr, das Gefängnis ist mir lieber als das, wozu sie mich auffordern“ (12:33). Er wählt das Gefängnis – und landet dort trotz bewiesener Unschuld. Al-Qurṭubī: Die Wahl der Reinheit kostet manchmal die Freiheit; Allah ehrt sie trotzdem."},
 {vers: "Verse 36–57: Gefängnis, Träume, Aufstieg", text: "Zwei Mitgefangene bitten um Traumdeutung. Yūsuf nutzt die Gelegenheit zuerst zur Daʿwa (12:37–40: „O meine beiden Gefängnisgefährten, sind verschiedene Herren besser oder Allah, der Eine, der Allbezwinger?“) – dann deutet er. Er bittet den Freigelassenen, ihn beim König zu erwähnen – der vergisst es, und Yūsuf bleibt „einige Jahre“. Dann der Traum des Königs (sieben fette, sieben magere Kühe), Yūsufs Deutung samt Wirtschaftsplan (sieben Jahre sparen, sieben Jahre verteilen). Der König will ihn sehen – Yūsuf weigert sich, das Gefängnis zu verlassen, bevor seine Unschuld öffentlich geklärt ist (12:50). Die Frau des ʿAzīz gesteht: „Jetzt ist die Wahrheit offenbar geworden; ich habe ihn verführen wollen.“ Yūsuf wird Schatzmeister: „Setze mich über die Vorratskammern des Landes; ich bin ein kundiger Hüter (ḥafīẓun ʿalīm)“ (12:55) – Kompetenz und Integrität, wie qawī-amīn in Lektion 49."},
 {vers: "Verse 58–98: die Brüder kommen", text: "Die Hungersnot bringt die Brüder nach Ägypten, er erkennt sie, sie ihn nicht. Er verlangt, beim nächsten Mal den jüngsten Bruder Binyāmīn mitzubringen, versteckt ihre Ware in ihren Säcken. Yaʿqūb lässt Binyāmīn ziehen – „Allah ist der beste Hüter“. Yūsuf behält Binyāmīn durch die Becher-List zurück (nach den Gelehrten mit Binyāmīns Einverständnis, um den Bruder zu schützen). Yaʿqūb verliert nun den zweiten Sohn, weint, bis seine Augen weiß werden – und sagt wieder: ṣabrun dschamīl, „vielleicht bringt Allah sie mir alle zurück“, und: „Verzweifelt nicht an Allahs Erbarmen“ (12:87). Beim dritten Besuch gibt sich Yūsuf zu erkennen: „Wisst ihr, was ihr Yūsuf und seinem Bruder angetan habt?“ – „Bist du etwa Yūsuf?“ – „Ich bin Yūsuf … wer gottesfürchtig und geduldig ist – Allah lässt den Lohn der Gutes Tuenden nicht verloren gehen“ (12:90). Die Brüder gestehen; Yūsuf: „Kein Tadel über euch heute.“ Sein Hemd auf das Gesicht des Vaters – Yaʿqūb wird wieder sehend."},
 {vers: "Verse 99–111: Erfüllung und Lehre", text: "Die Familie kommt nach Ägypten, die Eltern auf dem Thron, alle verneigen sich – der Traum aus Vers 4 erfüllt sich (die Verneigung als Ehrbezeugung war damals erlaubt, im Islam ist sie vor Menschen verboten). Yūsufs Worte sind ein Meisterwerk des Adab: Er erwähnt die Befreiung aus dem Gefängnis – aber nicht den Brunnen, um die Brüder nicht zu beschämen; und er sagt, der Satan habe „zwischen mir und meinen Brüdern“ Zwietracht gesät – nicht: meine Brüder haben … Dann sein Gebet (12:101): „Mein Herr, Du hast mir Herrschaft gegeben und Deutung der Ereignisse gelehrt … lass mich als Gottergebener sterben und füge mich den Rechtschaffenen bei.“ Auf dem Gipfel der Macht bittet er um ein gutes Ende. Schluss: „In ihren Geschichten ist eine Lehre für die Verständigen“ (12:111)."}
],
ahadith: [
 {text: "Gefragt, wer der edelste Mensch sei: „… Yūsuf, der Prophet Allahs, Sohn des Propheten Allahs, Sohn des Propheten Allahs, Sohn des Freundes Allahs (Ibrāhīm).“", quelle: "Sahih al-Buchari, Nr. 3353; Sahih Muslim, Nr. 2378"},
 {text: "Unter den sieben, die Allah am Tag ohne Schatten in Seinem Schatten birgt: „… ein Mann, den eine Frau von Rang und Schönheit (zu sich) ruft, und er sagt: Ich fürchte Allah.“", quelle: "Sahih al-Buchari, Nr. 660; Sahih Muslim, Nr. 1031"},
 {text: "ʿĀʾischa in der Verleumdungsaffäre: „Ich finde für mich und euch kein besseres Gleichnis als den Vater Yūsufs: Schöne Geduld – und Allah ist Der, Den man um Hilfe bittet.“", quelle: "Sahih al-Buchari, Nr. 4750"},
 {text: "„Wäre ich so lange im Gefängnis gewesen wie Yūsuf, ich hätte dem Boten (des Königs) sofort zugesagt“ – Lob des Propheten ﷺ für Yūsufs Würde und Geduld.", quelle: "Sahih al-Buchari, Nr. 3372; Sahih Muslim, Nr. 151"}
],
hanafi: null,
umsetzung: [
 "Lerne ṣabrun dschamīl: Bei Verlust und Ungerechtigkeit klage Allah (12:86), aber nicht ständig Menschen. Notiere dir 12:18 und 12:87 („Verzweifelt nicht an Allahs Erbarmen“).",
 "Wende 12:5 an: Erzähle deine Pläne und Gaben nicht jedem – Neid ist real (vgl. Lektion 20). Weisheit beim Teilen ist kein Misstrauen, sondern Schutz.",
 "Übe lā tathrīb: Wenn jemand, der dir Unrecht tat, um Verzeihung bittet – verzeih ganz, ohne alte Vorwürfe aufzuwärmen. Yūsuf erwähnte nicht einmal den Brunnen.",
 "Für junge Menschen: Mach Yūsufs Satz (12:33) zu deiner Strategie bei Versuchung – lieber Verzicht und Nachteil als Sünde. Und meide Situationen ‚hinter verschlossenen Türen'.",
 "Bete wie Yūsuf auf dem Höhepunkt (12:101): tawaffanī musliman wa-alḥiqnī bi-ṣ-ṣāliḥīn – gerade wenn es dir gut geht."
]
},

// ───────────────────────── Lektion 54: Al-Ḥidschr ─────────────────────────
{
sure: 15, offb: 54, name: "Al-Ḥidschr", arab: "سُورَةُ الْحِجْرِ", de: "Al-Ḥidschr", verse: 99, ort: "Mekka",
zeit: "Spätmekkanisch – mit dem Befehl zur offenen Verkündigung und der Garantie der Bewahrung des Korans",
kurz: "Die Sure mit der größten Garantie des Korans: „Wir haben die Ermahnung herabgesandt, und Wir werden über sie wachen.“ Vierzehn Jahrhunderte später ist kein Buchstabe verändert – das ist eingelöstes Versprechen. Ihr Name kommt von al-Ḥidschr, dem Felsental der Ṯamūd (heute Madāʾin Ṣāliḥ / al-ʿUlā), deren in Felsen gehauene Häuser sie nicht schützten. Die Sure erzählt noch einmal die Schöpfung Ādams aus „Ton von geformtem Schlamm“, Iblīs' Weigerung und Allahs Zusage: „Über Meine Diener hast du keine Macht.“ Dazu die Gäste Ibrāhīms und Lūṭs. Und am Ende drei Befehle für jede Zeit: „Verkünde offen, was dir befohlen wird“, „preise deinen Herrn und gehöre zu denen, die sich niederwerfen“ und „diene deinem Herrn, bis die Gewissheit zu dir kommt“.",
schluessel: {arab: "إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ", ueb: "Wir, ja Wir haben die Ermahnung herabgesandt, und Wir werden wahrlich über sie wachen.", ref: "15:9"},
kontext: ["Al-Ḥidschr gehört zu den Alif-Lām-Rā-Suren (vgl. Lektion 51) der späten mekkanischen Phase. Die Quraisch spotteten: „O du, auf den die Ermahnung herabgesandt wurde – du bist wahrlich besessen“ (15:6; vgl. Lektion 2). Die Antwort ist 15:9: Dieser Koran braucht nicht euren Schutz und nicht euer Urteil – Allah selbst bewahrt ihn. Die Gelehrten betonen den Unterschied zu früheren Schriften: Die Tora wurde den Rabbinern anvertraut („mit dem, was ihnen von der Schrift Allahs zur Bewahrung aufgetragen worden war“, 5:44) – den Koran bewahrt Allah selbst.",
"Wie wörtlich sich das erfüllt hat, ist Teil der Glaubenserfahrung: Der Koran wurde zu Lebzeiten des Propheten ﷺ aufgeschrieben und auswendig gelernt, unter Abū Bakr als Buch gesammelt, unter ʿUthmān in Abschriften an alle Provinzen geschickt – und wird seitdem durch Millionen Ḥuffāẓ in jeder Generation bewahrt. Würde man heute alle Mushafs der Welt vernichten, könnte man ihn aus den Herzen in einem Tag vollständig wiederherstellen.",
"Mit 15:94 („So verkünde offen, was dir befohlen wird, und wende dich von den Götzendienern ab“) wird nach den Mufassirūn der Schritt von der verdeckten zur vollständig offenen Daʿwa bekräftigt. Und 15:97–99 gibt dem Propheten ﷺ das Rezept gegen den Schmerz der Ablehnung: „Wir wissen, dass deine Brust beengt wird von dem, was sie sagen. So preise deinen Herrn mit Lob, sei unter denen, die sich niederwerfen, und diene deinem Herrn, bis die Gewissheit zu dir kommt.“ Gegen Enge der Brust: Tasbīḥ, Sudschūd, ʿIbāda."],
asbab: ["Für Al-Ḥidschr ist kein Einzelanlass sahih überliefert. Zu 15:95 („Wir genügen dir gegen die Spötter“) nennen die Tafsir-Werke fünf namentlich bekannte Spötter Mekkas (u. a. al-Walīd ibn al-Muġīra, al-ʿĀṣ ibn Wāʾil), die alle ein elendes Ende fanden (Tafsir-Bericht, u. a. bei aṭ-Ṭabarānī, Kette diskutiert)."],
begriffe: [
 {arab: "الذِّكْر", tr: "adh-dhikr", wurzel: "dh-k-r", erkl: "„Die Ermahnung/Erinnerung“ – ein Name des Korans: Er erinnert an das, was die fiṭra eigentlich weiß (vgl. Lektion 39). Bewahrt wird nach den Gelehrten der Wortlaut UND seine Bedeutung durch die Sunna."},
 {arab: "حَافِظُون", tr: "ḥāfiẓūn", wurzel: "ḥ-f-ẓ", erkl: "„Die Bewahrer“ (15:9) – mit doppelter Bekräftigung (innā … la-): Allah verbürgt sich selbst. Dieselbe Wurzel wie ḥāfiẓ (Lektion 36) und ḥifẓ (Koran auswendig lernen): Jeder Ḥāfiẓ ist ein Teil dieser Bewahrung."},
 {arab: "صَلْصَال", tr: "ṣalṣāl", wurzel: "ṣ-l-ṣ-l", erkl: "„Klingender (trockener) Ton“ (15:26) – lautmalerisch: Ton, der klingt, wenn man daran klopft. Der Mensch aus Ton, die Dschinn aus „Feuer des glühenden Windes“ (15:27). Die Materialien sind verschieden; der Rang kommt aus dem Einhauchen des Geistes (15:29)."},
 {arab: "عِبَادِي", tr: "ʿibādī", wurzel: "ʿ-b-d", erkl: "„Meine Diener“ (15:42): „Über Meine Diener hast du keine Macht, außer über die Abirrenden, die dir folgen.“ Wer sich bewusst als Diener Allahs versteht, steht unter einem Schutz, den Iblīs selbst eingesteht (vgl. 38:83, Lektion 38)."},
 {arab: "غِلّ", tr: "ġill", wurzel: "ġ-l-l", erkl: "„Groll“ (15:47): „Wir nehmen weg, was an Groll in ihren Brüsten ist – als Brüder auf Liegen einander gegenüber.“ Im Paradies gibt es keine Bitterkeit. Wer schon hier am Groll arbeitet, lebt ein Stück Paradies vorweg."},
 {arab: "الْيَقِين", tr: "al-yaqīn", wurzel: "y-q-n", erkl: "„Die Gewissheit“ (15:99) – nach dem Konsens der Mufassirūn: der Tod, das einzige völlig Gewisse. Gottesdienst endet nicht mit ‚Erleuchtung' oder Alter, sondern erst mit dem letzten Atemzug."}
],
tafsir: [
 {vers: "Verse 1–25: Spott und Bewahrung", text: "„Vielleicht werden die Ungläubigen wünschen, sie wären Muslime gewesen“ (15:2) – am Jüngsten Tag. „Lass sie essen und genießen und von Hoffnung abgelenkt sein (yulhihimu l-amal)“ (15:3) – al-amal, die endlose Hoffnung auf ‚später', ist eine der größten Fallen. Der Spott („du bist besessen“, „bring doch Engel!“) und die Antwort 15:9. 15:14–15: Selbst wenn ein Tor zum Himmel offen stünde und sie hinaufstiegen, würden sie sagen: „Unsere Blicke sind nur getrübt.“ Dann die Zeichen: Sternbilder, die Erde mit festen Bergen und „allem in rechtem Maß“, die Winde als Befruchter (lawāqiḥ – die Wolken und Pflanzen befruchtend), und 15:21: „Es gibt nichts, dessen Schatzkammern nicht bei Uns wären; Wir senden es nur in bekanntem Maß herab.“"},
 {vers: "Verse 26–48: Ādam, Iblīs und Meine Diener", text: "Der Mensch aus klingendem Ton, die Dschinn aus Feuer. Iblīs weigert sich: „Ich werde mich nicht vor einem Menschen niederwerfen, den Du aus Ton erschaffen hast.“ Er erhält Aufschub und kündigt an: „Ich werde ihnen auf der Erde (die Sünde) ausschmücken (la-uzayyinanna) und sie alle verführen – außer Deinen auserlesenen Dienern“ (15:39–40). Ibn Kathīr: Die Methode des Satans ist Verschönerung – Sünde sieht nie hässlich aus, wenn sie lockt. Allahs Antwort 15:42: keine Macht über Meine Diener. Die Hölle hat sieben Tore; die Gottesfürchtigen sind in Gärten und Quellen, ohne Groll, ohne Mühe, ohne Vertreibung. Dann 15:49–50 in perfekter Balance: „Tu Meinen Dienern kund, dass Ich der Allvergebende, der Barmherzige bin – und dass Meine Strafe die schmerzhafte Strafe ist.“ Hoffnung und Furcht in zwei Versen."},
 {vers: "Verse 49–84: die Gäste, Lūṭ und al-Ḥidschr", text: "Die Engel bei Ibrāhīm – „Wir verkünden dir einen kenntnisreichen Jungen“; Ibrāhīm: „Wer verzweifelt an der Barmherzigkeit seines Herrn außer den Irregehenden?“ (15:56). Dann bei Lūṭ: Die Stadt kommt, „sich freuend“ über die fremden Gäste; Lūṭ fleht: „Das sind meine Gäste, stellt mich nicht bloß.“ Der Schrei am Morgen, die Stadt umgestürzt, Steine aus gebranntem Ton – „Darin sind Zeichen für die, die Merkmale deuten“ (15:75 – lil-mutawassimīn: die mit Scharfsinn hinschauen). Dann die Leute des Dickichts (Schuʿaibs Volk) und die Leute von al-Ḥidschr (Ṯamūd): „Sie meißelten aus den Bergen Häuser, in Sicherheit“ – „und nicht nützte ihnen, was sie erworben hatten“ (15:82–84)."},
 {vers: "Verse 85–99: die Sieben, die offene Verkündigung und die Gewissheit", text: "„Wir haben die Himmel und die Erde nicht anders als in Wahrheit erschaffen … so verzeih auf schöne Weise (aṣ-ṣafḥ al-dschamīl)“ (15:85 – vgl. ṣabr dschamīl, hadschr dschamīl: der Koran liebt das Schöne auch in der Haltung). 15:87: „Wir haben dir sieben von den Mathānī gegeben und den gewaltigen Koran“ – nach dem Hadith die Fātiḥa (Sahih al-Buchari, Nr. 4474; vgl. Lektion 5). 15:88: „Richte deine Augen nicht auf das, was Wir einigen Paaren von ihnen zum Genuss gegeben haben … und senke deinen Flügel für die Gläubigen.“ Dann 15:94 (offen verkünden), 15:95 („Wir genügen dir gegen die Spötter“) und das Seelsorge-Ende 15:97–99. As-Saʿdī: Die Medizin gegen die Enge der Brust ist nicht Rückzug, sondern mehr ʿIbāda – bis zum Tod."}
],
ahadith: [
 {text: "Als der Prophet ﷺ auf dem Weg nach Tabūk an al-Ḥidschr vorbeizog: „Betretet nicht die Wohnstätten derer, die sich selbst Unrecht taten, außer weinend – damit euch nicht trifft, was sie traf.“ Er verhüllte sein Haupt und beschleunigte, bis er das Tal durchquert hatte.", quelle: "Sahih al-Buchari, Nr. 433 und 4702; Sahih Muslim, Nr. 2980"},
 {text: "„Al-ḥamdu lillāhi rabbi l-ʿālamīn – sie ist die sieben Mathānī und der gewaltige Koran, der mir gegeben wurde.“ – zu 15:87.", quelle: "Sahih al-Buchari, Nr. 4474"},
 {text: "„Wenn die Gläubigen vom Feuer gerettet sind, werden sie auf einer Brücke zwischen Paradies und Hölle festgehalten, wo untereinander Vergeltung geübt wird für Unrecht, das zwischen ihnen im Diesseits war – bis sie gereinigt und geläutert sind; dann wird ihnen der Eintritt ins Paradies erlaubt.“ – zum Wegnehmen des Grolls (15:47).", quelle: "Sahih al-Buchari, Nr. 2440"},
 {text: "„Allah hat die Barmherzigkeit in hundert Teile geteilt; neunundneunzig behielt Er bei Sich, einen sandte Er auf die Erde herab …“ – zu 15:49.", quelle: "Sahih al-Buchari, Nr. 6000; Sahih Muslim, Nr. 2752"}
],
hanafi: null,
umsetzung: [
 "Werde Teil von 15:9: Lerne eine Sure mehr auswendig, als du heute kannst – jeder Ḥāfiẓ, auch der von wenigen Suren, trägt die Bewahrung des Korans mit.",
 "Wenn dir die Brust eng wird (15:97): Verschreibe dir das Rezept der Sure – Tasbīḥ, eine extra Sadschda, eine extra ʿIbāda. Nicht weniger Religion, sondern mehr Nähe.",
 "Arbeite an deinem ġill (15:47): Gibt es jemanden, gegen den du Groll trägst? Bete heute für ihn – das ist der schnellste Weg, Groll aufzulösen.",
 "Halte 15:49–50 im Gleichgewicht: Lies diese beiden Verse, wenn du zu sicher wirst (Furcht) oder zu verzweifelt (Hoffnung).",
 "Nimm 15:99 als Lebensplan: Es gibt keinen ‚Ruhestand' vom Gottesdienst – aber auch keinen Grund zur Hast. Beständig bis zur Gewissheit."
]
}
];
